// Texto: INTRODUCCIÓN_v46, anexo §3.4; lectura, datación y clasificación: DVC_v5_FINAL.xlsx (hoja Datos).
export const INTRO_AUTOPSIAS = ["Este anexo recoge los resultados de las autopsias realizadas en la Eforía de Antigüedades de Ioánina en 2024 y 2025. Las de 2024 se centraron en las consultas con mezcla dialectal y en algunas de adscripción dudosa; las de 2025, en la relación entre el alfabeto y el dialecto y en las inscripciones cuyo alfabeto se había identificado con dudas o no se correspondía con su dialecto. Cada laminilla ocupa un párrafo y, dentro de cada campaña, se ordenan por su número de inventario del museo (M), acompañado del número de inventario arqueológico (AMI). Tras el número de fragmentos, su estado y la fecha de la autopsia, se recogen las observaciones de cada inscripción: la datación de la edición, el orden en que se grabó respecto a las demás, las manos, la confirmación o la corrección de la lectura y, cuando la escritura tiene consecuencias para el alfabeto o el dialecto, los datos correspondientes, con la remisión al capítulo en que se estudia. Se incluyen también las inscripciones que no se estudian en ningún capítulo, porque el orden de grabado y las manos de una laminilla afectan a la interpretación de todos sus textos."];
export const CAMPANAS_AUTOPSIAS = {"2024": "Las autopsias de 2024 se realizaron entre el 20 de noviembre y el 19 de diciembre de 2024 y abarcaron 45 laminillas con 169 inscripciones, 127 de ellas con observaciones propias.", "2025": "Las autopsias de 2025 se realizaron en octubre de 2025 y abarcaron 26 laminillas con 101 inscripciones, 92 de ellas con observaciones propias."};
// Una entrada por laminilla; obs = null: inscripción sin observaciones propias.
export const LAMINILLAS_AUTOPSIA = [{"key": "M20", "siglum": "M20", "ami": "ΑΜΙ 12209", "anio": 2024, "fecha": "20 de noviembre de 2024", "nota": "Un fragmento, con un agujero que ya existía cuando se grabó 5A, cuyo autor lo evitó, pero no cuando se grabó 7B, a la que atraviesa, de modo que la cara B es anterior a la A. Las dos caras conservan restos de otras inscripciones.", "items": [{"id": "5A", "dialect": "noJonAt", "sub": null, "date": "Mediados del s. V a.C.", "text": "Κλεάνορι περὶ γενεᾶς \nπατρο̅ιό̅χο̅ ἐκ τᾶς νῦν \nἐόνθας γυναικός.", "obs": "Al comienzo de la línea 1 se distingue una Γ que el facsímil no recoge, quizá de otra inscripción, porque es mayor que las demás letras, y al comienzo de la línea 2, un trazo que podría ser una iota. En la línea 2, antes de ἐκ, hay un guion inscrito. La lectura ἐόνθας es segura. Cf. cap. 4, §5.2.6."}, {"id": "6A", "dialect": "dorico", "sub": null, "date": "Mediados del s. V a.C.", "text": "ἐ͂ πέπατα(ι) καὶ πεπαμέ-\nνος λό̅ϊόν κα πράσ(σ)οι", "obs": "Grabada en sentido inverso al de 5A. Se confirma el alfabeto corintio: la épsilon corintia nota todas las /e/, y la Ε, la /ɛː/. Cf. cap. 4, §3."}, {"id": "7B", "dialect": "noJonAt", "sub": null, "date": "Mediados del s. V a.C.", "text": "ἐ͂ Ϝοίκοι κα λό̅ϊον \nπράσσοιμι καὶ τυγ-\nχάνοι παίδο̅ν ἱλασ-\n[κ]όμεν[ος];", "obs": "Hay restos de otra inscripción entre sus líneas. Es anterior al agujero de la laminilla y, por tanto, a 5A. Emplea la digamma en forma de F y la épsilon corintia para la /ɛː/ de la línea 1, pero escribe con Ε la /e/ de la línea 4. Cf. cap. 15 (anexo)."}, {"id": "8B", "dialect": "sinClasificar", "sub": null, "date": "Mediados del s. V a.C.", "text": "προβατεύο̅ ἒ̅ μέ̅;", "obs": "Grabada en sentido inverso al de 7B, con trazos tenues."}], "facsimiles": ["assets/autopsias/5A/facsimil-5a.jpg"]}, {"key": "M51", "siglum": "M51", "ami": "ΑΜΙ 12198", "anio": 2024, "fecha": "20 de noviembre de 2024", "nota": "Dos fragmentos; la laminilla se partió después de grabarse todas las inscripciones. La cara A contiene una sola inscripción, completa, y la B, tres.", "items": [{"id": "31A", "dialect": "tesalio", "sub": null, "date": "Mediados del s. IV a.C.", "text": "Αἰ τυχαία μοι ἁ ἑπι-\nτροπεία τὰν ἔχου \nτᾶμον Λυκκίδας ;", "obs": "Escritura regular y clara. Se confirma la lectura τᾶμον, frente al γᾶμον de Evangelidis. En la línea 2, la Χ y la Ο de ἔχου son más pequeñas y están algo elevadas. Cf. cap. 7, §3.1.1.1 y §6."}, {"id": "32B", "dialect": "noJonAt", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "Πὲρ τᾶς γυν-\nαικὸς καὶ\nαὕτα ἔχει\nἀσφαλ[έω]ς ;", "obs": "Se confirma la lectura de la edición, frente a las de Evangelidis y Lhôte; en el hueco de la laminilla caben dos letras, como en la restitución ἀσφαλ[έω]ς. Cf. cap. 7, §4.1, y cap. 15 (anexo)."}, {"id": "33B", "dialect": "mezcla", "sub": null, "date": "Ss. V-IV a.C.", "text": "Εὐρ[. . . .]χων \nἐπε[ρωτῆ ἦ τ]ὰ χρήματ-\nα Χ̣ιόνη κα ἔκλεψε \nκαὶ [. . .] ΣΑΜΑΤΙΣΑΙ", "obs": "Grabada en sentido inverso al de I.Dodone DVC 32B y debajo de ella. La eta de ΧΙΟΝΗ se ve, aunque no con claridad, porque está muy desgastada, y pertenece a esta inscripción, lo que apoya la lectura Χιόνη, y con ella la mezcla dialectal, frente a Ϝιονίκα; la digamma inicial que esa lectura supone no es posible. En la ny de ΧΙΟΝΗ hay un trazo inferior, como si se hubiera escrito una alfa. Cf. cap. 13, §4.5."}, {"id": "34B", "dialect": "sinClasificar", "sub": null, "date": "S. V a.C.", "text": "[ὁ δεῖνα] ἐπε(ύ)χε[ται - - -]\n[- - -]ΞΟΙ[. . . 5 . . .] γενεὰ [- - -]\n[- - - γένοι]το γενε[ὰ - - -]", "obs": "Grabada debajo de I.Dodone DVC 32B y, por tanto, anterior a ella; está borrada en parte. Cf. cap. 13, §4.5."}], "facsimiles": []}, {"key": "M82", "siglum": "M82", "ami": "ΑΜΙ 12176", "anio": 2024, "fecha": "20 de noviembre de 2024", "nota": "Un fragmento, partido por la derecha. La cara B solo conserva restos ilegibles de otras inscripciones.", "items": [{"id": "75", "dialect": "tesalio", "sub": null, "date": "Ss. V-IV a.C.", "text": "ποιτηρο͂-\nν ΓΑΡΟΤΕ-\nΟΥ ὅπερ τᾶμον καὶ εἴ 'σστ-\nι τύχα", "obs": "Letras claras, de trazos tan nítidos que permiten reconocer el orden en que se trazó cada letra. La lectura coincide con el facsímil, y la inscripción se grabó en la laminilla ya cortada; no hay trazos a la derecha de τύχα, de modo que no puede restituirse τυχαῖος. Cf. cap. 7, §6."}], "facsimiles": []}, {"key": "M86", "siglum": "M86", "ami": "ΑΜΙ 12178", "anio": 2024, "fecha": "20 de noviembre de 2024", "nota": "Tres fragmentos. Las dos caras conservan restos de otras inscripciones.", "items": [{"id": "82A", "dialect": "doricoNO", "sub": null, "date": "Finales del s. V a.C.", "text": "τὸ σαμῆον τὸ ἐν Ὀφινίωι οὐκ ἔστι Προδάμου̣", "obs": "Entre ΟΦΙ y ΝΙΩΙ hay un hueco en el que cabe exactamente una letra, como en la lectura Ὀφι[ο]νίωι de <i>CIOD</i>, y bajo la ómicron de Ὀφινίωι se aprecian trazos de una Κ, lo que confirma que se escribió una kappa y se corrigió después, como proponen los editores. De la ípsilon final solo queda un trazo. Cf. cap. 5, §2."}, {"id": "83B", "dialect": "sinClasificar", "sub": null, "date": "Finales del s. V a.C.", "text": "Θέμοτος", "obs": "De otra mano que I.Dodone DVC 82A."}], "facsimiles": []}, {"key": "M87", "siglum": "M87", "ami": "ΑΜΙ 12187", "anio": 2024, "fecha": "20 de noviembre de 2024", "nota": "Cinco fragmentos, con una laguna en la parte central derecha. La cara B solo conserva restos de otras inscripciones.", "items": [{"id": "84", "dialect": "noJonAt", "sub": null, "date": "Finales del s. V a.C.", "text": "[θ]εὸς τύχα ἀγαθά• \n[ο]ὐκ αἴτιος Δαύλιος \n[τ]οῦ θανάτο̅ τοῦ [Ἑ]ρ-\nμαίο̅", "obs": "La laminilla está en peor estado del que muestra la edición: la laguna es mayor, de la ípsilon de Δαυ[λ]ιος apenas se lee nada y de la épsilon de [Ἑ]ρμαίο̄ no queda ningún trazo. Cf. cap. 15 (anexo)."}], "facsimiles": []}, {"key": "M100", "siglum": "M100", "ami": "ΑΜΙ 12184", "anio": 2024, "fecha": "16 de diciembre de 2024", "nota": "Un fragmento. La cara B solo conserva restos ininteligibles de otras inscripciones.", "items": [{"id": "123", "dialect": "jonicoAtico", "sub": "Ático", "date": "Segunda mitad del s. IV a.C.", "text": "[Θεός• Φ]ανόστρατος ὦ Ζ̣εῦ ἐρωτᾶι \n[εἰ λ]ώϊον καὶ ἄμεινον καὶ πρᾶ-\n[γμ' ἀ]γ̣αθὸν διαλεγομέν(ωι) Ἰφικρά-\n[τει ἃ ἐ]ν νῶι ἔχω καὶ ποιομένωι \n[αὐτ]ὸν φίλον", "obs": "La sigma tiene los trazos medios muy cortos, con una forma próxima a la lunar, salvo en la línea 3. En la línea 2, la alfa de καί corrige una rho, como muestran los trazos. Cf. cap. 11, §2 y §4.1."}], "facsimiles": []}, {"key": "M152", "siglum": "M152", "ami": "ΑΜΙ 12260", "anio": 2024, "fecha": "21 de noviembre de 2024", "nota": "Cuatro fragmentos.", "items": [{"id": "126A", "dialect": "noJonAt", "sub": null, "date": "S. IV a.C.", "text": "θεὸς τύχα• ἦ τύ[χ]οιμί κα το[ῦ] \nθησαυροῦ ποταναι̣ρέων ΟΥΝ[.] \n[. . . 5 . . .]ΑΜΕΠΟΤΕΤΑ ἐργ(ά)ζεται τυν̣-\n[χάνοι] κα <ἐν̣> ἐν γαία κατθεῖσα \n[. . . 5 . . .] αὕτα τὸν θησαυρόν τε οὐ ποταναιρε[ῖ];", "obs": "Escritura regular, de una sola mano en toda la inscripción, frente a la división en dos consultas que se propone en <i>CIOD</i>. La parte izquierda se ha perdido en parte. El ΟΥΝ final de la línea 2 es más pequeño, quizá por falta de espacio, y ποταναιρε[ῖ] está escrito entre las líneas 4 y 5. Cf. cap. 15 (anexo)."}, {"id": "127A", "dialect": "noJonAt", "sub": null, "date": "S. IV a.C.", "text": "θεὸς τ(ύ)χα• - [Θ]έτιμος τ[οῦ] \nθεοῦ̣ δεῖται πότ̣ε̣ρα [.]Α[. .] \n[- - -] νόον [. . .]", "obs": "Grabada debajo de I.Dodone DVC 126A y, por tanto, anterior a ella. Cf. cap. 15 (anexo)."}, {"id": "128A", "dialect": "noJonAt", "sub": null, "date": "S. IV a.C.", "text": "Ἕρμων• πυθέσθαι ὦ Ζεῦ Νᾶε \nκαὶ Θέμι καὶ Διώνα θεμίστευ<ε>-\nσον ὅ,τι μέλλει λώϊστον καὶ ἄ-\nριστον", "obs": "Grabada debajo de I.Dodone DVC 126A, en el espacio que quedaba libre. El nombre Ἕρμων se lee con dificultad, sobre todo la omega, cruzada por trazos de otras inscripciones. Cf. cap. 15 (anexo)."}, {"id": "129A", "dialect": "noJonAt", "sub": null, "date": "S. IV a.C.", "text": "[- - - ] Ϝοικ[- - - πρ]ά̣σ(σ)ο̅ καὶ [- - -]\n[- - -]ΑΙ[.]ΕΠ[- - -] \n[- - -]ΛΕΟ[- - -]", "obs": "Grabada debajo de I.Dodone DVC 128A. La parte izquierda se lee bien, pero la derecha está casi borrada. Cf. cap. 15 (anexo)."}, {"id": "130A", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - -]ΑΙΛΕΙΑ", "obs": "Grabada en sentido inverso al de las demás inscripciones de la cara A. Cf. cap. 11, §4.5, y cap. 13, §4.1."}, {"id": "131B", "dialect": "noJonAt", "sub": null, "date": "Finales del s. IV a.C.", "text": "[Ἀ]ριστοτέλε̅[ς] περὶ \nπράξιων ἇν ἐντεθύ-\nμητα̣ι π(ρά)σ(σ)οντι ἄ-\nμεινον", "obs": "La lectura es segura. Entre la Τ y la Ε de ΕΝΤΕΘΥ, en la línea 2, hay una alfa escrita por error, y ΘΥ, al final de la línea, está algo elevado. Cf. cap. 15 (anexo)."}, {"id": "132B", "dialect": "sinClasificar", "sub": null, "date": "Finales del s. IV a.C.", "text": "Α", "obs": "Una sola letra, de gran tamaño, grabada debajo de I.Dodone DVC 131B."}, {"id": "133B", "dialect": "mezcla", "sub": null, "date": "Mediados del s. IV a.C.", "text": "[θεὸ]ς τύχα• Λαχάρης δεῖ(τ)αι \nτοῦ θε[οῦ] εἰ̣ οἴκαδε ἀπιό(ν)τι κα-\nὶ ἐργαζομένωι<ν> οἱ βέλτιόν ἐστι", "obs": "Grabada en sentido inverso al de I.Dodone DVC 131B, con letras pequeñas y erosionadas. En la línea 2, los trazos de εἰ son extremadamente finos. Cf. cap. 13, §4.1."}, {"id": "134B", "dialect": "noJonAt", "sub": null, "date": "S. IV a.C.", "text": "ἐπιθύ[σ]εα π̣ότ̣ερόν \nκα λό̅ϊό[ν μ]οι [τυγχ]άνοι;", "obs": "Grabada debajo de I.Dodone DVC 131B, con letras pequeñas y erosionadas. Cf. cap. 15 (anexo)."}], "facsimiles": []}, {"key": "M153", "siglum": "M153", "ami": "ΑΜΙ 12240", "anio": 2024, "fecha": "16 de diciembre de 2024", "nota": "Un fragmento. I.Dodone DVC 136B queda sin observaciones propias.", "items": [{"id": "135A", "dialect": "dorico", "sub": null, "date": "Segunda mitad del s. V a.C.", "text": "ἦ Μιλήϊός τις ἐναν̣-\nτίος hόρο̅ δύνατ-\nαι Ϝοικε͂σαι;", "obs": "Letras regulares y esquemáticas, semejantes a las de las inscripciones públicas. La Η nota tanto la /ɛː/ como la aspiración. En Μιλήϊος, la iota tiene los trazos de una Η, como si se hubiera escrito dos veces por vacilación, y la ny final que lee la edición se ha borrado por completo. En la línea 3, la letra que la edición lee como Ε en Ϝοικε͂σαι es una épsilon corintia, de modo que la consulta nota la /ɛː/ unas veces con la Η y otras con la épsilon corintia, que en la línea 1 nota la /e/. Cf. introducción, §3.2.2, cap. 4, §4.1.3, y cap. 13, §5.4."}, {"id": "136B", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "ἐ͂ μένω̣;", "obs": null}, {"id": "137B", "dialect": "sinClasificar", "sub": null, "date": "Mediados del s. V a.C.", "text": "ἐο͂ν", "obs": "Grabada en sentido inverso al de I.Dodone DVC 136B. Es de la misma mano que I.Dodone DVC 135A: la primera letra es una épsilon corintia de la misma forma que la de Ϝοικε͂σαι."}], "facsimiles": ["assets/autopsias/135A/facsimil-135a.jpg"]}, {"key": "M204", "siglum": "M204", "ami": "ΑΜΙ 12299", "anio": 2024, "fecha": "21 de noviembre de 2024", "nota": "Un fragmento. La cara B conserva, además de I.Dodone DVC 270B y 271B, restos de otras inscripciones.", "items": [{"id": "268A", "dialect": "severior", "sub": null, "date": "Ss. V-IV a.C.", "text": "[θεὸς τύχα• ἐρωτ]ε͂ι ἁ πόλις \n[τῶν Δωδωνα]ίων τὸν Δί-\n[α τὸν Νᾶο]ν καὶ τὰν Δι-\n[ώναν περὶ τ]ῶ σαμείω τῷ \n[- - -]γενομένω τί \n[κα εἴη λώϊ]ον καὶ ἂμει-\n[νον - - -] ἢ̣ μηδὲν \n[- - - γέν]οιτο", "obs": "La laminilla se partió después de grabarse la inscripción, de modo que no puede saberse la extensión de la laguna izquierda. Las lecturas son seguras, y la omega tiene el mismo tamaño que las demás letras. En la línea 2 parece haber una iota completa, y no el resto de la ny que supone la lectura [Ταραντι]ν̣ων de <i>CIOD</i>. Cf. cap. 6, §3 y §4.1.2."}, {"id": "269A", "dialect": "sinClasificar", "sub": null, "date": "Principios del s. IV a.C.", "text": "[- - -]ΓΑΙΠΑ", "obs": "Grabada encima de I.Dodone DVC 268A y, por tanto, posterior a ella."}, {"id": "270B", "dialect": "sinClasificar", "sub": null, "date": "Principios del s. IV a.C.", "text": "Ἀφρόδο-\nτος", "obs": "Al comienzo de la línea 2 hay una omega que parece pertenecer a la inscripción; quizá el consultante vaciló entre Ἀφροδώτος y Ἀφροδότος."}, {"id": "271B", "dialect": "jonicoAtico", "sub": null, "date": "S. IV a.C.", "text": "ἐπ[ε]ρω̣τᾶ[ι ὁ δεῖνα - - -]\nπότε[ρα - - -] \nΑΙ[- - -]", "obs": "La inscripción se ha borrado desde la lectura de la edición; de la omega de la línea 1 solo quedan trazos indeterminados. Cf. cap. 7, §3.1.2."}], "facsimiles": []}, {"key": "M205", "siglum": "M205", "ami": "ΑΜΙ 12267", "anio": 2024, "fecha": "21 de noviembre de 2024", "nota": "Tres fragmentos. I.Dodone DVC 274B queda sin observaciones propias.", "items": [{"id": "272A", "dialect": "mezcla", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "εἰ δὲ μὴ εἰ κακουργεῖται ναύκλε̅ρος ὑπὸ φαρμάκων μη δεῖ\nΔΕ [. . . .]ΕΝ πραγματεύεσθαι ἀλλ' ἐσσεῖται αὐτῶι \nκ̣αὶ ἄνευ πραγματείας ἐ[ξ] Ἀριστοβίας ΠΕ[. .] Α [. . .] \n[ὀν]ασίφορο̅ς οὗτος ἑξεῖ;", "obs": "Letras regulares y muy finas, con la sigma lunar de trazos rectos. La primera iota de la línea 1 tiene otros trazos y su lectura no es segura. ναύκλε̄ρος está escrito sobre la línea 1, encima de ὑπὸ φαρμά-, por la misma mano que el resto; también la segunda Λ de ἀλλ᾽ y la segunda Σ de ἐσσεῖται, en la línea 2, se añadieron sobre la línea. En la línea 3, la Ξ se lee bien, frente a la edición. Cf. cap. 13, §4.2."}, {"id": "273A", "dialect": "noJonAt", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "θε[ὸς τύχ]α ἀγαθά· ἐ[π]ερωτ[ῆι ὁ δεῖνα - - -]", "obs": "Grabada en sentido inverso al de I.Dodone DVC 272A, con letras minúsculas. Cf. cap. 15 (anexo)."}, {"id": "274B", "dialect": "noJonAt", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "[- - -]\n[Ἀθάναι Π]ο̣λιάδι [- - -] \n[Τύχαι] Ἀγαθᾶι, Δίκ[αι - - -]", "obs": null}], "facsimiles": []}, {"key": "M230 + M541", "siglum": "M230 + M541", "ami": "ΑΜΙ 12231 + 12649", "anio": 2024, "fecha": "22 de noviembre de 2024", "nota": "Dos fragmentos hallados en excavaciones distintas, que pertenecen a la misma laminilla. Cada cara tiene dos inscripciones.", "items": [{"id": "357A", "dialect": "mezcla", "sub": null, "date": "Principios del s. IV a.C.", "text": "Θεός. Τύχη. Ἐπικοινῆται Ἀλκίνο[ος τῶι] \nΔιὶ τῶι Ναίωι καὶ τᾶι Διώναι εἰ λ[ῶιον] \n[καὶ] ἄμεινον Νικέαν κατασκευάζ[ειν] \nτὸ ἐργαστήριον.", "obs": "La laminilla se ha desgastado por la izquierda desde la lectura de la edición, y las primeras letras de las líneas 1 y 2 se han borrado. La lectura del resto es segura. Cf. cap. 13, §4.2."}, {"id": "358B", "dialect": "sinClasificar", "sub": null, "date": "Principios del s. IV a.C.", "text": "[- - -]ΗΒΙ\n[- - -]ΔΕ", "obs": "Grabada en vertical respecto de I.Dodone DVC 357A; a su izquierda hay trazos ilegibles."}, {"id": "359B", "dialect": "jonicoAtico", "sub": null, "date": "Principios del s. IV a.C.", "text": "θεὸς ἀγαθὴ τύχη• Ὀνήσιμος ἐ[περωτᾶι] \nΔία τὸν Νάϊ[ο]ν καὶ τὴν Διώνη(ν) τί[να θεῶν ἢ] \nἡρώων ἱλασκόμενος ὑγιαίνο̣[ι - - -] \nἐ̣πιτυγχάνη [. .]Ε[.]ΑΝ", "obs": "Esta cara está más erosionada que la A. En la línea 4, en el hueco que la edición deja en Ε[.]ΑΝ, hay trazos que apuntan a una Λ, y tras ἐπιτυγχάνη caben exactamente dos letras, como supone la edición. Emplea la sigma lunar y su escritura parece más reciente que la de I.Dodone DVC 357A, pero está grabada debajo de I.Dodone DVC 360B, que parece de la mano de I.Dodone DVC 357A: o bien I.Dodone DVC 360B no es de esa mano, o bien convivieron dos tipos de escritura muy distintos. Cf. cap. 9, §4."}, {"id": "360B", "dialect": "sinClasificar", "sub": null, "date": "Principios del s. IV a.C.", "text": "Νικέα", "obs": "Grabada encima de I.Dodone DVC 359B. Parece de la misma mano que I.Dodone DVC 357A, aunque no tiene letras diagnósticas."}], "facsimiles": []}, {"key": "M238", "siglum": "M238", "ami": "ΑΜΙ 12308", "anio": 2024, "fecha": "16 de diciembre de 2024", "nota": "Tres fragmentos.", "items": [{"id": "377A", "dialect": "noJonAt", "sub": null, "date": "Primera mitad del s. V a.C.", "text": "θεὸς τύχα• τὰν ἑστίαν καὶ Ϝο̣[ι]-\nκίαν τυν̣χ(ά)νο̅ ἐχϜο[ι]κ̣έο̅ν;", "obs": "En la línea 2, las letras son más pequeñas, como si faltara espacio, y la iota de Ϝο̣[ι]κίαν queda bajo la kappa. La digamma tiene forma de F. Cf. cap. 15 (anexo)."}, {"id": "378B", "dialect": "sinClasificar", "sub": null, "date": "Primera mitad del s. V a.C.", "text": "Κλε", "obs": "La primera letra, que la edición lee como Κ, parece más bien una alfa de forma poco habitual (ΑΛΕ)."}, {"id": "379B", "dialect": "sinClasificar", "sub": null, "date": "Primera mitad del s. V a.C.", "text": "Εὔφαμο[ς - - -]", "obs": "Grabada en sentido inverso al de I.Dodone DVC 378B, en la parte izquierda de la laminilla."}], "facsimiles": []}, {"key": "M382", "siglum": "M382", "ami": "ΑΜΙ 12449", "anio": 2024, "fecha": "22 de noviembre de 2024", "nota": "Tres fragmentos. La cara B conserva, además, restos ilegibles de otras inscripciones. I.Dodone DVC 856B queda sin observaciones propias.", "items": [{"id": "854A", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "ἦ τυγχάνοι [.][- - -]\n[- - - - - - -];", "obs": "Parece el comienzo de la inscripción; quedan restos ilegibles de una segunda línea."}, {"id": "855A", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - -]Α \n[- - -]ΩΝ", "obs": "Muy deteriorada; la primera línea ya no se ve."}, {"id": "856B", "dialect": "noJonAt", "sub": null, "date": "Principios del s. IV a.C.", "text": "Ϝιστ̣όρε̅κα Ἀμ̣φ̣ίαρος τὸ̣[ν θεὸν - - - ἀφ]-\nέντος ἄνθρ̣ο̅πο̣ν ΟΕ̣[- - -]", "obs": null}, {"id": "857B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - -]ας", "obs": "Grabada en sentido inverso al de I.Dodone DVC 856B."}, {"id": "858B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[ὁ δεῖνα ἐπερωτῆι] τὸν θε[ὸν - - -]", "obs": "Grabada en sentido inverso al de I.Dodone DVC 856B y antes que ella; hoy apenas se lee a simple vista."}, {"id": "859B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - -π]ότερα [- - -]", "obs": "Grabada en sentido inverso al de I.Dodone DVC 856B y encima de ella."}], "facsimiles": []}, {"key": "M427", "siglum": "M427", "ami": "ΑΜΙ 12487", "anio": 2024, "fecha": "22 de noviembre de 2024", "nota": "Dos fragmentos. La cara B conserva, además de I.Dodone DVC 1014B, restos de otras inscripciones. I.Dodone DVC 1011A queda sin observaciones propias.", "items": [{"id": "1011A", "dialect": "noJonAt", "sub": null, "date": "Principios del s. IV a.C.", "text": "θεὸς τύχα· περὶ [.][- - -] \nΝικάνωρ νικα[- - -]", "obs": null}, {"id": "1012A", "dialect": "mezcla", "sub": null, "date": "Finales del s. V a.C.", "text": "περὶ τῶ ἀνδριάντος \nτῶ ἐκ τῶ ἱερῶ τῶ Ἀρτέ-\nμιδως̣", "obs": "Grabada en sentido inverso al de I.Dodone DVC 1011A y debajo de ella. La lectura es segura, también la de las formas de la <i>Doris severior</i>, y la omega no es más pequeña que las demás letras. Cf. cap. 6, §4.1.2, y cap. 13, §4.6."}, {"id": "1013A", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "ἦ οὔ;", "obs": "Grabada arriba a la izquierda de I.Dodone DVC 1012A, en el espacio libre."}, {"id": "1014B", "dialect": "mezcla", "sub": null, "date": "Principios del s. IV a.C.", "text": "Φιλίσκος εἰρωτᾶι \nεἰ ἄμεινον αὐτῶι \nἐργάζεσθαι κατὰ γᾶν", "obs": "La superficie está muy rayada, pero la lectura es segura. En la línea 3, la gamma de γᾶν tiene un segundo trazo horizontal, como una F. Cf. cap. 10, §4.7, y cap. 13, §4.3."}], "facsimiles": []}, {"key": "M432", "siglum": "M432", "ami": "ΑΜΙ sin identificar", "anio": 2024, "fecha": "19 de diciembre de 2024", "nota": "Un fragmento, expuesto en el Museo Arqueológico de Ioánina. I.Dodone DVC 1025A+B ocupa las dos caras.", "items": [{"id": "1025A+B", "dialect": "mezcla", "sub": null, "date": "Finales del s. IV a.C.", "text": "Όψη Β\nΠερὶ Δαματρίο(υ)\n\nΌψη Α\nκαὶ Διονυσίω καρπ̣[ῶ]", "obs": "La inscripción empieza en la cara B y continúa en la A, de la misma mano en las dos caras pese a pequeñas diferencias. Se grabó después de I.Dodone DVC 1026A y 1027B. Tras καρπ-, al final de la cara A, no se lee la omega de la lectura de Lhôte. Cf. cap. 13, §4.6."}, {"id": "1026A", "dialect": "noJonAt", "sub": null, "date": "Finales del s. IV a.C.", "text": "ἦ Μένω̣ν (π)ερὶ τᾶ(ς) : τέχνα[ς - - -];", "obs": "Anterior a I.Dodone DVC 1025A+B. Los tres puntos en vertical son del consultante."}, {"id": "1027B", "dialect": "sinClasificar", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "ἦ ἐσῆτε σωτηρία̣ τοῦ̣ παιδὸς [. .][- - -];", "obs": "Anterior a I.Dodone DVC 1025A+B, que se grabó encima; letras pequeñas y desgastadas."}], "facsimiles": []}, {"key": "M446", "siglum": "M446", "ami": "ΑΜΙ 12534", "anio": 2024, "fecha": "22 de noviembre de 2024", "nota": "Un fragmento. I.Dodone DVC 1075A y 1077B quedan sin observaciones propias.", "items": [{"id": "1075A", "dialect": "noJonAt", "sub": null, "date": "Finales del s. V a.C.", "text": "[θεὸς τύχα]ν ἀγαθάν· Τίμων Πυραῖο[ς ἐπερωτῆι - - -] \n[- - -]αταν πὸ(τ) τὸν Δία Νά[ϊον - - -]", "obs": null}, {"id": "1076A", "dialect": "noJonAt", "sub": null, "date": "Principios del s. IV a.C.", "text": "[πε]ρὶ τᾶς δι[- - -] \n[α]ἰ ἀκέωμ[αι]", "obs": "Grabada encima de I.Dodone DVC 1075A."}, {"id": "1077B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "ἔσστι", "obs": null}, {"id": "1078B", "dialect": "doricoNO", "sub": null, "date": "Finales del s. V a.C.", "text": "[θεὸς τύ]χ̣αν ἀγαθάν· Κλεοξενος [ἐπερωτᾶι - - -]\n[- - -]ΣΥ̣ΝΑΟΚΕΘΟΝΤΟΣ καὶ τᾶς θυ[σίας - - -]", "obs": "Grabada debajo de I.Dodone DVC 1077B. La primera línea se lee bien; la segunda está algo borrada. Cf. cap. 5, §4.1.2.4."}, {"id": "1079B", "dialect": "sinClasificar", "sub": null, "date": "Mediados del s. IV a.C.", "text": "[- - - ἄμεινον καὶ λ]ό̅ϊον το͂(ν) χρε̅μά[το̅ν - - -] \n[- - -][.]ΑΣΤΡΣ[- - -]", "obs": "Grabada en sentido inverso al de I.Dodone DVC 1077B."}, {"id": "1080B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - -] τίνα̣ [θεῶν θεραπεύων - - -]", "obs": "Grabada en sentido inverso al de I.Dodone DVC 1077B y encima de ella."}, {"id": "1081B", "dialect": "sinClasificar", "sub": null, "date": "Principios del s. IV a.C.", "text": "Α", "obs": "Grabada encima de I.Dodone DVC 1077B y debajo de I.Dodone DVC 1078B."}], "facsimiles": []}, {"key": "M473", "siglum": "M473", "ami": "ΑΜΙ 12541", "anio": 2024, "fecha": "28 de noviembre de 2024", "nota": "Tres fragmentos que forman dos secciones, hoy imposibles de unir: la primera, con un agujero, lleva I.Dodone DVC 1187A, 1188A y 1189B; la segunda, I.Dodone DVC 1190A, 1191B y 1192B. I.Dodone DVC 1189B, 1190A y 1192B quedan sin observaciones propias.", "items": [{"id": "1187A", "dialect": "noJonAt", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "[περὶ τᾶς τύ]χας τοῦ Κταίβα", "obs": "A la izquierda se lee ΠΙ, que parece de otra inscripción. El facsímil no reproduce bien algunas letras: la Χ tiene la forma de los alfabetos “rojos”, la sigma tiene tres trazos y no cuatro, y la épsilon es angulosa, como la épsilon corintia antigua. Cf. cap. 15 (anexo)."}, {"id": "1188A", "dialect": "sinClasificar", "sub": null, "date": "Ss. IV-III a.C.", "text": "[- - -]Ο̣ΝΑ", "obs": "Grabada en sentido inverso al de I.Dodone DVC 1187A."}, {"id": "1189B", "dialect": "noJonAt", "sub": null, "date": "S. IV a.C.", "text": "[- - -]ΛΠΕΑ[- - -] \n[- - -] αἰ δὲ μὴ [- - -];", "obs": null}, {"id": "1190A", "dialect": "noJonAt", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "θεὸς τύχα ἀγαθά· Ζε[ῦ] Νάϊε καὶ Δι[ώνα] \nἦ λώϊόγ κα πράσσοι Θ̣έγειτος τὰ [- - -];", "obs": null}, {"id": "1191B", "dialect": "noJonAt", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "[θ]εὸς τύχαν ἀγ[αθάν· ἐπερωτῆι] \n[Π]αρμενίων πε[ρὶ - - -]", "obs": "Cara muy erosionada."}, {"id": "1192B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "Α[. ][- - -]", "obs": null}], "facsimiles": []}, {"key": "M502", "siglum": "M502", "ami": "ΑΜΙ 12685", "anio": 2024, "fecha": "28 de noviembre de 2024", "nota": "I.Dodone DVC 1304A, 1305A, 1307B, 1308, 1309B y 1311B quedan sin observaciones propias.", "items": [{"id": "1303A", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[ἦ γυναῖκα ἀ]γόμενος;", "obs": "La laminilla ya estaba partida cuando se grabó: sin espacio para el final, el autor escribió más abajo la secuencia ΝΟ y debajo de ella la sigma."}, {"id": "1304A", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - -]ΑΣΟΜ[- - -]", "obs": null}, {"id": "1305A", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "πὲρ [. . .5 . .][- - -] \nΑ[. . . . .9 . . . .][- - -]", "obs": null}, {"id": "1306A", "dialect": "noJonAt", "sub": null, "date": "S. IV a.C.", "text": "Μεγακλῆ̣ς ἐρωτ̣[ῆι - - - ἦ] \nτ̣υχάνο̣ι κα ἰὼ[ν - - -]", "obs": "Se conserva peor de lo que muestra el facsímil. Al final del nombre se lee una omega entre la eta y la sigma, y la eta apenas se distingue, de modo que la lectura Μεγακλῆ̣ς no es segura; de ἐρωτ- solo se ve el trazo vertical de la rho, y la tau final no se lee. Cf. cap. 15 (anexo)."}, {"id": "1307B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "Ζεῦ Νά[ϊε - - -] \n[. .]ΟΑΙΝ[.][- - -]", "obs": null}, {"id": "1308", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "Θε[- - -]", "obs": null}, {"id": "1309B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - -][.]ΡΕΘ[- - -]", "obs": null}, {"id": "1310B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[ὁ δεῖνα ἐπερωτῆι Δία] Νάϊον \n[- - -][. .]ΑΤΙΟΙΣ πράσ-\n[σοιμι - - -]", "obs": "En la línea 1 se lee ΝΑΘΙΟΝ: la theta que el facsímil atribuye a I.Dodone DVC 1309B pertenece, por su posición y por sus trazos, a esta inscripción."}, {"id": "1311B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - -][. . .] τἀνδρά̣-\n[ποδα - - -]", "obs": null}], "facsimiles": []}, {"key": "M597", "siglum": "M597", "ami": "ΑΜΙ 12610", "anio": 2024, "fecha": "28 de noviembre de 2024", "nota": "Dos fragmentos. La cara B conserva, además, restos de otras inscripciones. I.Dodone DVC 1616B queda sin observaciones propias.", "items": [{"id": "1613A", "dialect": "noJonAt", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "θεὸς τύχα· Με(γα)κλῆς \nΣΑΜΑΝΟΙΚ[.]ΑΛΕ[. .]ΕΙ τὰν Διών-\nαν καὶ τὸν Δ̣ία τὸν Νάϊον \nϜοικίαν", "obs": "El nombre coincide con el de I.Dodone DVC 1306A, pero las manos son distintas. ΚΛΗ, en la línea 1, está algo elevado. Cf. cap. 15, §4."}, {"id": "1614A", "dialect": "sinClasificar", "sub": null, "date": "Principios del s. IV a.C.", "text": "θεὸς· [ὁ δεῖνα ἐπερωτῆι - - -]\nκαὶ Γ[- - -]", "obs": "Grabada debajo de I.Dodone DVC 1613A."}, {"id": "1615A", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "πε[ρὶ - - -]", "obs": "Grabada en vertical respecto de I.Dodone DVC 1613A y 1614A."}, {"id": "1616B", "dialect": "noJonAt", "sub": null, "date": "Finales del s. V a.C.", "text": "ἦ ἀπονοῆσ̣αι περ̣ὶ τού-\nτας τᾶς γυναικὸς ΑΕΡΜΕΝ̣[- - -];", "obs": null}, {"id": "1617B", "dialect": "noJonAt", "sub": null, "date": "Principios del s. IV a.C.", "text": "θεὸς τύχα· [ περ]-\nὶ σωτηρίας", "obs": "Grabada encima de I.Dodone DVC 1616B. Cf. cap. 15 (anexo)."}], "facsimiles": []}, {"key": "M605", "siglum": "M605", "ami": "ΑΜΙ 12591", "anio": 2024, "fecha": "28 de noviembre de 2024", "nota": "Un fragmento. La cara B conserva, además, restos de otras inscripciones. I.Dodone DVC 1641B queda sin observaciones propias.", "items": [{"id": "1640A", "dialect": "mezcla", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "[- - - Ζεῦ] Νάϊε [Δι]ών[α], \n[- - -] Σάμας [. . .5 . .] \n[- - -]ΕΙΤΑΙ[. . .5 . .] \n[- - -] τῶι 'δελφεῶι \n[- - - ἄμειν]ομ πρήξει", "obs": "La lectura es segura, aunque desde la de la edición se han borrado ΙΕ de Νάϊε, en la línea 1, y la primera sigma de la línea 2. Cf. cap. 10, §4.7, y cap. 13, §4.5."}, {"id": "1641B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - -]ΕΙΤΑ[.]Ρ̣Ο[- - -]", "obs": null}, {"id": "1642B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - - περὶ] γυναι[κὸς] \n[- - -][.] ταῦτα", "obs": "Grabada debajo de I.Dodone DVC 1641B."}], "facsimiles": []}, {"key": "M714", "siglum": "M714", "ami": "ΑΜΙ 12768", "anio": 2024, "fecha": "29 de noviembre de 2024", "nota": "Siete fragmentos.", "items": [{"id": "2005A", "dialect": "noJonAt", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "[ἦ] σύνοιδε Μίρ<ι>ων καὶ Εὐθύδ[αμος καὶ - - -κιος] \nκαὶ Μέλισ(σ)α τᾶν ὑῶν τ̣ᾶνν Χ[. . .]νος [- - -]\nἀνέ̣κλεψε;", "obs": "Escritura irregular. La primera sigma de la línea 1 se ha perdido en el primer pliegue. En la línea 2, la letra que la edición lee como chi tiene la forma de la chi de los alfabetos “rojos”, que es la misma de la psi de ἀνέκλεψε en la línea 3, de modo que el mismo signo tendría dos valores en una sola inscripción; siguen un hueco de dos letras y ΗΝΟΣ. Cf. introducción, §2.3.3."}, {"id": "2006A", "dialect": "sinClasificar", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "[- - - οὐκ ἐ]δ̣έξατο Μίρων οὐδ' Εὐθύδ̣αμος \n[οὐδὲ - - -]κι[ο]ς οὐδὲ Μέλισσα τὰ̣ς ὕας τ̣ὰς \n[Χαρῖνος ἀνέκλεψε] οὐδὲ συγκατέφαγον", "obs": "Grabada en sentido inverso al de I.Dodone DVC 2005A, con letras más pequeñas y regulares; la theta, la sigma y la ípsilon tienen formas distintas de las de I.Dodone DVC 2005A. Cf. introducción, §2.3.3."}, {"id": "2007B", "dialect": "noJonAt", "sub": null, "date": "Sin datación en la edición", "text": "[ἦ τ]ὰ̣ν γᾶν̣ [ἐργάζωμαι];", "obs": "Grabada en vertical respecto de I.Dodone DVC 2005A. Cf. cap. 15 (anexo)."}], "facsimiles": []}, {"key": "M722", "siglum": "M722", "ami": "ΑΜΙ 12784", "anio": 2024, "fecha": "29 de noviembre de 2024", "nota": "Un fragmento. I.Dodone DVC 2019B queda sin observaciones propias.", "items": [{"id": "2018A", "dialect": "mezcla", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "Νικόδωρος̣ τῶι̣ \nΔιὶ ε̣ἰ μὴ̣ ἔστι νό-\nσ̣τος αὐτῶι οἴ[κ]-\nαδε ὀνάσιμ̣[ο]-\nς", "obs": "La épsilon de εἰ, en la línea 2, que la edición da como dudosa, solo ha perdido el trazo horizontal inferior, y la lectura es segura. La ómicron y la omega tienen el mismo tamaño que las demás letras. Cf. cap. 13, §4.3."}, {"id": "2019B", "dialect": "sinClasificar", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "[ὁ δεῖνα ἐπερω]τ̣εῖ τὸν Δία κ̣αὶ [τὰν Διώναν] \n[- - - θε]οῖς θύων τὰ ΟΛΙ[. .][- - -]", "obs": null}], "facsimiles": []}, {"key": "M769", "siglum": "M769", "ami": "ΑΜΙ 12900", "anio": 2024, "fecha": "29 de noviembre de 2024", "nota": "Cuatro fragmentos. La cara B conserva, además, restos de otras inscripciones. I.Dodone DVC 2172B queda sin observaciones propias.", "items": [{"id": "2169A", "dialect": "mezcla", "sub": null, "date": "Mediados del s. IV a.C.", "text": "[Ζε]ῦ Νάϊ[ε] Διώνα, αἴ μοι \n[μένοντ]ι ἐν τ[ῆ]ι οἰκίαι ἧι νῦν \n[οἰκ]έω καὶ λ[ώ]ϊον καὶ ἄμει-\n[νο]ν καὶ αὐτ[ῶ]ι καὶ τέκνη[ι] \nκα[ὶ χ]ρήμα[σι]", "obs": "La línea 1 difiere ligeramente de las demás, porque su ómicron tiene el tamaño de las demás letras, mientras que en el resto del texto es mucho más pequeña; en la línea 4, τέκνη está escrito con letras menores. Cf. cap. 13, §4.2 y §5.2."}, {"id": "2170B", "dialect": "noJonAt", "sub": null, "date": "Ss. V-IV a.C.", "text": "θεὸς τύχαν ἀγαθάν· αἰ\n[- - - - - - - - - - - -]", "obs": "Cara muy deteriorada."}, {"id": "2171B", "dialect": "noJonAt", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "Ἱστία καὶ ζεῦ Νάϊε καὶ Διώνα, \nπότερά κα συναλλάσων ὄ[ν]α̣[ιον] \nκαὶ ἄμεινον πράσσοιμι;", "obs": "Grabada encima de I.Dodone DVC 2170B, con letras muy pequeñas; la lectura es segura. Cf. cap. 15 (anexo)."}, {"id": "2172B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "Λ", "obs": null}], "facsimiles": []}, {"key": "M787", "siglum": "M787", "ami": "ΑΜΙ 12894", "anio": 2024, "fecha": "29 de noviembre de 2024", "nota": "Cuatro fragmentos.", "items": [{"id": "2225A", "dialect": "jonicoAtico", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "Θεογνήτωι εἰ \nδὲ μὴ ἔστι \nτούτω(ν) δὴ β̣-\nέντισ[το]ν", "obs": "Θεογνήτωι se lee con seguridad. En la línea 4, las letras que siguen a ΕΝ se han perdido por las fracturas de la laminilla, de modo que la lectura β̣έντισ[το]ν no puede asegurarse, ni, con ella, la mezcla dialectal. Cf. cap. 13, §4.7."}, {"id": "2226B", "dialect": "sinClasificar", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "ἦ μαστεύ̣-\nων;", "obs": "La laminilla ha perdido la parte superior desde la lectura de la edición. Cf. cap. 14, §4.1.4."}, {"id": "2227B", "dialect": "noJonAt", "sub": null, "date": "Ss. V-IV a.C.", "text": "Κίθ[ω]νι μὴ δικα-\nξά[μενος - - -]", "obs": "Grabada en sentido inverso al de I.Dodone DVC 2226B. En la línea 2, la xi tiene un trazo vertical que la atraviesa y que el facsímil no recoge. Cf. cap. 15 (anexo)."}], "facsimiles": []}, {"key": "M793", "siglum": "M793", "ami": "ΑΜΙ 12890", "anio": 2024, "fecha": "5 de diciembre de 2024", "nota": "Dos fragmentos. La laminilla ya estaba partida cuando se grabó I.Dodone DVC 2246A, que no ocupa el segundo fragmento. I.Dodone DVC 2249B queda sin observaciones propias.", "items": [{"id": "2246A", "dialect": "noJonAt", "sub": null, "date": "Mediados del s. IV a.C.", "text": "ἐπερ̣ωτῆι Εὐμέδων τὸν Δία τὸν̣ Δωδω̣ν̣αῖο̣[ν] \nπότερόν οἱ λώϊον καὶ ἄμεινον ἐπεργαζο-\nμένωι τὰν τέχναν ἃν ἔχει", "obs": "En la línea 1 se lee ΔΩΥΔΩΝΑΙΟ, con una ípsilon tras la primera omega que la edición no recoge; quizá se escribió por error, pero recuerda a la forma Δουδωναῖος de I.Dodone DVC 2204A y 3817B. Cf. cap. 7, §3.1.1.1."}, {"id": "2247A", "dialect": "tesalio", "sub": null, "date": "Finales del s. IV a.C.", "text": "εἶ οὐ ἔσσεται;", "obs": "Grabada en sentido inverso al de I.Dodone DVC 2246A, cuyas letras no coinciden con las suyas. Cf. cap. 7, §3.1.1.1."}, {"id": "2248A", "dialect": "noJonAt", "sub": null, "date": "Finales del s. IV a.C.", "text": "Αἰ <κ>α Φιλίσστας ἀξίωτο νοσέ̅ματος", "obs": "Grabada encima de I.Dodone DVC 2246A. Cf. cap. 15 (anexo)."}, {"id": "2249B", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "Καλλ", "obs": null}, {"id": "2250B", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "εἰ [. .][- - -]", "obs": "Grabada en el hueco entre la kappa y ΑΛΛ de I.Dodone DVC 2249B."}, {"id": "2251B", "dialect": "doricoNO", "sub": null, "date": "Mediados del s. IV a.C.", "text": "[- - -] ἀγαθὰ πραξοῦ[μες - - -] \n[- - -]ΜΑ καὶ ἐνταῦτ̣[α - - -] \n[- - -]ΟΥ πάντε[ς - - -]", "obs": "Grabada debajo de I.Dodone DVC 2249B. La xi de πραξοῦ[μες] tiene la forma Ξ, y no la que reproduce el facsímil. Cf. cap. 5, §5.2.3."}, {"id": "2252B", "dialect": "jonicoAtico", "sub": null, "date": "Mediados del s. IV a.C.", "text": "[- - -]των εἰ μὴ<η> ἀγαθῶι", "obs": "Grabada en sentido inverso al de I.Dodone DVC 2251B. Cf. cap. 9 (anexo)."}, {"id": "2253B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[ἦ] οὔ;", "obs": "Grabada detrás de I.Dodone DVC 2252B, con la misma ípsilon que I.Dodone DVC 2247A, a la que probablemente responde."}], "facsimiles": []}, {"key": "M797", "siglum": "M797", "ami": "ΑΜΙ 12885", "anio": 2024, "fecha": "29 de noviembre de 2024", "nota": "Cinco fragmentos; el de la parte superior derecha se ha perdido desde la lectura de la edición.", "items": [{"id": "2261A", "dialect": "mezcla", "sub": null, "date": "Ss. V-IV a.C.", "text": "[θ]εοὶ \n[ἀγαθὴ] τύχη· \n[Ζε]ῦ Δωδωναῖε \n[κ]αὶ Διώνη : (ἄ)με̅νον πράσ(σ)οι· \nεἰ λῶον καὶ ἄ[μ]ε̣̅ν̣ο̣ν \nΜενάν̣δρωι πλέον-\nτι μετὰ Θηρ(α)μένο̅ \nκαὶ νῦν καὶ : ἰς τὸν ἐπί-\nλο(ι)πον χρόνον λῶον καὶ Α̣ \n καὶ ὅτω ἄν τις θεῶν̣ [θύοι]", "obs": "Los dos signos de dos puntos son del consultante. A partir de los segundos, en la línea 8, las omegas tienen el mismo tamaño que las demás letras, y la escritura cambia. La alfa final de la línea 9 parece de otra inscripción. En la línea 10, que empieza con una sangría de tres letras, hay una iota entre ΟΤΩ y ΑΝ que la edición no recoge en el texto, aunque sí en el facsímil. Cf. cap. 12, §4, y cap. 13, §4.4."}, {"id": "2262A", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "χρόνο[ν - - -]", "obs": "Grabada entre las líneas 2 y 3 de I.Dodone DVC 2261A, con letras parecidas a las de esta, quizá de la misma mano."}, {"id": "2263B", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "τὸ μὴ ΝΟΟΜΟΝΙ", "obs": "Cara muy deteriorada; solo se ve esta línea."}], "facsimiles": []}, {"key": "M806", "siglum": "M806", "ami": "ΑΜΙ 12871", "anio": 2024, "fecha": "5 de diciembre de 2024", "nota": "Dos fragmentos. La cara A conserva, además, restos ilegibles de otras inscripciones. I.Dodone DVC 2293B queda sin observaciones propias.", "items": [{"id": "2291A", "dialect": "mezcla", "sub": null, "date": "Mediados del s. IV a.C.", "text": "ἐπερωτῆ (τ)ὸν Δία καὶ Διώ̣[ναν ὁ δεῖνα ἦ τὰν] \nγᾶν γεωργῶ", "obs": "En la línea 2, la gamma de γᾶν está escrita sobre una Λ: el consultante escribió ΛΑΝ y lo corrigió en ΓΑΝ. Las formas de la alfa y de la rho difieren entre las dos líneas, que quizá son independientes. Cf. cap. 13, §4.3."}, {"id": "2292A", "dialect": "sinClasificar", "sub": null, "date": "Mediados del s. IV a.C.", "text": "[ὁ δεῖνα ἐπικοιν]ῆται [- - -]", "obs": "Grabada en sentido inverso al de I.Dodone DVC 2291A; detrás se advierten trazos de otras inscripciones."}, {"id": "2293B", "dialect": "jonicoAtico", "sub": null, "date": "Mediados del s. IV a.C.", "text": "ἐρο̅τᾶι [ὁ δεῖνα]", "obs": null}], "facsimiles": []}, {"key": "M815", "siglum": "M815", "ami": "ΑΜΙ 12856", "anio": 2024, "fecha": "5 de diciembre de 2024", "nota": "Un fragmento, doblado por la mitad. Un trazo horizontal cruza toda la cara B.", "items": [{"id": "2319A", "dialect": "jonicoAtico", "sub": "Jónico", "date": "Ss. V-IV a.C.", "text": "Κράτων ἐπερωτᾶι τὸν θεὸν \nπερὶ τῶν καρπῶν ὧν ἡ γῆ φύ-\nει ἦ ἂν ἐντελέες \nγίνωνται", "obs": "La tau y la omega de Κράτων se han borrado por una marca de la laminilla, y las ny de τὸν θεόν se añadieron después, algo elevadas. En la línea 3, el consultante dejó un hueco de cuatro o cinco letras, con trazos de otras inscripciones, tras el que se lee un signo que parece combinar Γ, Κ y Η, donde la edición lee ἦ. Cf. cap. 9, §6, y cap. 10, §4.3."}, {"id": "2320A", "dialect": "sinClasificar", "sub": null, "date": "Sin datación en la edición", "text": "Ζ", "obs": "Una zeta, grabada en el hueco de la línea 3 de I.Dodone DVC 2319A."}, {"id": "2321B", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "ἄ̣νθρο̅π[ος - - -]", "obs": "Grabada encima del trazo horizontal que cruza la cara B."}], "facsimiles": []}, {"key": "M823", "siglum": "M823", "ami": "ΑΜΙ 12843", "anio": 2024, "fecha": "2024", "nota": "Dos fragmentos. La cara B solo conserva restos ininteligibles de otras inscripciones. I.Dodone DVC 2354A y 2355A quedan sin observaciones propias.", "items": [{"id": "2354A", "dialect": "noJonAt", "sub": null, "date": "Mediados del s. IV a.C.", "text": "Φυσαίων ἐπερωτεῖ Δ[ί]α Νά-\nϊον καὶ Διώνα(ν) ἦ διαβαίνη τᾶι \nḥιαρομηνίαι εἰς Ἀκαρνανία[ν] \nἦ πράξε̣ι τι ὧν κα χρεῖ κατὰ \nγνώμαν ἀσφαλέως", "obs": null}, {"id": "2355A", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - -] καὶ [.]ΟΜ[- - -]", "obs": null}], "facsimiles": []}, {"key": "M826", "siglum": "M826", "ami": "ΑΜΙ 12863", "anio": 2024, "fecha": "5 de diciembre de 2024", "nota": "Tres fragmentos. I.Dodone DVC 2359A queda sin observaciones propias.", "items": [{"id": "2359A", "dialect": "jonicoAtico", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "θεός· \nΛυσίθεος καὶ Κτησ[- - - ἐπερωτῶσι τὸν Δία] \nΝαέα καὶ τὴν Διώ[νην - - -] \nγνώμην αὐτοῖς Π[- - - τίνι ἂν θεῶν ἢ ἡ]-\nρώων εὐχομένοις [- - -]\nΜΗΝ καὶ περὶ τῶν Α[- - -]", "obs": null}, {"id": "2360B", "dialect": "sinClasificar", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "Λυσίθεος", "obs": "De la misma mano que I.Dodone DVC 2359A."}, {"id": "2361B", "dialect": "doricoNO", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "[- - - π]ο̣ρ̣ευσοῦμαι \n[- - -][.]ΝΑ οὕτα<α>ν νῦ[ν]", "obs": "Grabada encima de I.Dodone DVC 2362B. Cf. cap. 5, §5.2.3."}, {"id": "2362B", "dialect": "noJonAt", "sub": null, "date": "Finales del s. V a.C.", "text": "[θεός· ἐπερωτῆι] Φιλώτα γυνὰ \n[Δία Νάϊον καὶ τὰ]ν Διώναν τίν[ι] \n[κα θεῶν θύουσα ἢ] ἡρώων κατὰ γνώ-\n[μαν - - -]Α[.] περὶ πάντων", "obs": "Grabada debajo de I.Dodone DVC 2361B. Cf. cap. 15 (anexo)."}, {"id": "2363B", "dialect": "sinClasificar", "sub": null, "date": "Principios del s. IV a.C.", "text": "ΕΛΑΙΕ̣[- - -] \nπλέω;", "obs": "Grabada en sentido inverso al de I.Dodone DVC 2362B."}], "facsimiles": []}, {"key": "M848", "siglum": "M848", "ami": "ΑΜΙ 12832", "anio": 2024, "fecha": "6 de diciembre de 2024", "nota": "Un fragmento, con un pliegue en el centro. La cara A conserva, además, restos de otras inscripciones.", "items": [{"id": "2430A", "dialect": "jonicoAtico", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "ἦ ἀλλότριον καὶ οὐ τήνδε;", "obs": "De otra mano que I.Dodone DVC 2432B. Cf. cap. 13, §4.7."}, {"id": "2431A", "dialect": "sinClasificar", "sub": null, "date": "Sin datación en la edición", "text": "[πε]ρὶ [- - -]", "obs": "Grabada en sentido inverso al de I.Dodone DVC 2430A."}, {"id": "2432B", "dialect": "noJonAt", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "ἐξελεῖν τὰν ἀ̣γριέλαιον τῶ̣[ι]-\nδε ἥρωι ἁ̣γ̣νᾶς καθ(α)ρᾶς ὧραι ἀργ̣[αί]", "obs": "De otra mano que I.Dodone DVC 2430A: la rho, la delta, la alfa y la ny tienen formas distintas. Cf. cap. 13, §2.3 y §4.7."}], "facsimiles": []}, {"key": "M861", "siglum": "M861", "ami": "ΑΜΙ 12822", "anio": 2024, "fecha": "6 de diciembre de 2024", "nota": "Un fragmento, muy alargado. I.Dodone DVC 2472B queda sin observaciones propias.", "items": [{"id": "2470A", "dialect": "mezcla", "sub": null, "date": "Ss. V-IV a.C.", "text": "θεὸς τύχα : ἦ τὰν : Κράτεα̣(ν) \n Καλλί-\n δου;", "obs": "El consultante introdujo un salto de línea a causa de una marca de la laminilla, y las líneas se superponen; los dos signos de tres puntos son suyos. Cf. cap. 13, §4.5."}, {"id": "2471B", "dialect": "sinClasificar", "sub": null, "date": "Mediados del s. IV a.C.", "text": "ἦ καὶ ἀλλῶς εὑρήσω;", "obs": "Emplea la sigma lunar."}, {"id": "2472B", "dialect": "sinClasificar", "sub": null, "date": "Sin datación", "text": "ΙΙΙ", "obs": null}], "facsimiles": []}, {"key": "M874", "siglum": "M874", "ami": "ΑΜΙ 12943", "anio": 2024, "fecha": "6 de diciembre de 2024", "nota": "Dos fragmentos, inscritos por una sola cara.", "items": [{"id": "2506", "dialect": "mezcla", "sub": null, "date": "Ss. V-IV a.C.", "text": "καὶ Η[. . .]ΜΟΥΔ[. .] [ἐ]-\nρωτᾶι τὸν θεὸν εἰ \nγυναῖκ̣α ἀγαγόμε-\nνος βέλτιον πρά-\nσ(σ)οι", "obs": "Nada indica que se haya perdido una línea superior, como supone la edición. En la línea 1, la letra que sigue a καί, que la edición lee como Η, no conserva ningún trazo horizontal y encaja mejor con una Π, y tras ΜΟΥΔ se ven los trazos de una V. En la línea 3, el consultante escribió ΓΝΝ por ΓΥΝ. La sigma tiene una forma próxima a la lunar, salvo en la línea 4, donde tiene cuatro trazos. Cf. cap. 12, §4, y cap. 13, §4.4."}], "facsimiles": []}, {"key": "M906", "siglum": "M906", "ami": "ΑΜΙ 12976", "anio": 2024, "fecha": "6 de diciembre de 2024", "nota": "Dos fragmentos; el primero, con tres pliegues. I.Dodone DVC 2611B y 2612B quedan sin observaciones propias.", "items": [{"id": "2609A", "dialect": "mezcla", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "ἀ(γα)θὴ τύχη· ἐπερωτῆι Πλαυρ̣ά̣τα τὸν Δία [καὶ τὰν] \nΔιώνα(ν) ἦ ἐντ(υ)γχάνουσα Πλάτωνι Κάρπω[νος] \nΑ̣ΙΔΑΓΟΝΝΟΙΣ[.]ΙΟΓΟΙΣ ἐσεῖταί μοι ἀγαθὸν \nκαὶ ὠφέλε̣ια", "obs": "En la línea 1, ἐπερωτῆ no lleva al final la iota que restituye la edición. En ἐσεῖται, la iota no se lee, pero el hueco que ocupa es claro. Cf. cap. 13, §4.2."}, {"id": "2610A", "dialect": "noJonAt", "sub": null, "date": "Finales del s. IV a.C.", "text": "[- - -]ος [ἐρωτῆι Δία] τὸν Νᾶον καὶ τὰν \n[Διώναν - - -] τάχι[στα] [. . . .]ΑΙ πλέ[ο]ντι [. . . 6 . . .]\n[- - - β]έ̣[λτιο]ν καὶ ἄμεινον πράξει", "obs": "Grabada en sentido inverso al de I.Dodone DVC 2609A. Cf. cap. 15 (anexo)."}, {"id": "2611B", "dialect": "sinClasificar", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "ΠΟ", "obs": null}, {"id": "2612B", "dialect": "sinClasificar", "sub": null, "date": "Finales del s. V a.C.", "text": "[- - -]ΕΠΕ̣ \n[- - -]Η", "obs": null}], "facsimiles": []}, {"key": "M952", "siglum": "M952", "ami": "ΑΜΙ 12986", "anio": 2024, "fecha": "19 de diciembre de 2024", "nota": "I.Dodone DVC 2749A, 2750A y 2751B quedan sin observaciones propias.", "items": [{"id": "2749A", "dialect": "sinClasificar", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "[.]υναίτων ἀνερω[τεῖ Δία Νάϊον καὶ Διώναν] \n[π]ότερον ἐργάζε[σθαι κατὰ γᾶν καὶ τίνι κα θε]-\n[ῶ]ν ἢ θεᾶν εὐχό̣[μενος - - -]\n[.]ΜΙΩΝ δέομα[ι]", "obs": null}, {"id": "2750A", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "Λαε[- - -]", "obs": null}, {"id": "2751B", "dialect": "mezcla", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "Χάρμιππος̣ ἐρ-\nωτᾶι εἰ κατὰ γᾶ-\n[ν] ἐργάζηται", "obs": null}], "facsimiles": []}, {"key": "M1021", "siglum": "M1021", "ami": "ΑΜΙ 13121", "anio": 2024, "fecha": "6 de diciembre de 2024", "nota": "Cuatro fragmentos. La cara A tiene seis inscripciones y restos de otras; la B, tres. I.Dodone DVC 3013B y 3014B quedan sin observaciones propias.", "items": [{"id": "3007A", "dialect": "tesalio", "sub": "Histiótide", "date": "Ss. V-IV a.C.", "text": "π(ερ') ὕδ̣ατ̣(ο)ς : Τέ̅ϊος \nκαὶ Σθε̅σι", "obs": "La primera línea es mucho más fina que la segunda. Al comienzo de la línea 1 hay trazos de una ípsilon, quizá de otra inscripción, y tras ΠΡΕ, un trazo que la edición no recoge; los dos puntos de esa línea son del consultante, y la iota de Τε̄́ϊος está cruzada por un trazo horizontal. En σθε̄σι, en la línea 2, la theta lleva una Τ en su parte superior izquierda, como si se hubiera empezado a corregir en tau. Cf. introducción, §3.2.2, y cap. 7, §4.1."}, {"id": "3008A", "dialect": "tesalio", "sub": null, "date": "Ss. V-IV a.C.", "text": "ἐ͂ ἐλ λιμένι χαλκοπο̅λέμεν;", "obs": "Grabada encima de I.Dodone DVC 3007A. La segunda línea, τυχαία, que la edición no recoge, se lee con claridad y es de la misma mano que la primera; la inscripción está completa. Cf. introducción, §3.2.2, y cap. 7, §6."}, {"id": "3009A", "dialect": "sinClasificar", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "ἦ ἰατροῖς χρῶ[μαι];", "obs": "Grabada debajo de I.Dodone DVC 3008A."}, {"id": "3010A", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[Ἀρ]ι̣στομ̣είδ̣[ας]", "obs": "Grabada en sentido inverso al de I.Dodone DVC 3009A; la primera iota no se lee."}, {"id": "3011A", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "[- - -]Ο̣ΙΟ̣Ν[. .]Α̣ \n[πε]ρὶ γενεᾶς", "obs": "En la misma orientación que I.Dodone DVC 3010A. Emplea la gamma lunada y la épsilon corintia."}, {"id": "3012A", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "[ἦ] οὐκ ἔστι̣;", "obs": "Grabada encima de I.Dodone DVC 3011A."}, {"id": "3013B", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "[ἦ] Ἀριστέα[ς - - -]- \nα καλ[ῶ]ς;", "obs": null}, {"id": "3014B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[π]ερὶ τᾶ̣(ς) παρα̣[μονᾶς]", "obs": null}, {"id": "3015B", "dialect": "jonicoAtico", "sub": null, "date": "S. IV a.C.", "text": "[- - -]ΟΔΟΞΑΣ[. . .] εἰ προ[.][- - -]", "obs": "Grabada encima de I.Dodone DVC 3014B. Cf. cap. 9 (anexo)."}], "facsimiles": ["assets/autopsias/AMI-13121/facsimil-13121-cara-a.jpg", "assets/autopsias/AMI-13121/facsimil-3008a.jpg"]}, {"key": "M1024", "siglum": "M1024", "ami": "ΑΜΙ 13131", "anio": 2024, "fecha": "12 de diciembre de 2024", "nota": "Dos fragmentos. La cara B conserva, además de I.Dodone DVC 3023B, restos de otras inscripciones. I.Dodone DVC 3023B queda sin observaciones propias.", "items": [{"id": "3022A", "dialect": "mezcla", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "τί περὶ τῆς δί-\nκα(ς) ἐλπίδην;", "obs": "Lectura segura. La escritura es distinta de la de I.Dodone DVC 3023B, en la otra cara. Cf. cap. 13, §4.4."}, {"id": "3023B", "dialect": "noJonAt", "sub": null, "date": "Mediados del s. V a.C.", "text": "[Ἀ]δ̣έας π̣(ὲ)ρ τᾶ[ς] \nγενεᾶς", "obs": null}], "facsimiles": []}, {"key": "M1034", "siglum": "M1034", "ami": "ΑΜΙ 13108", "anio": 2024, "fecha": "6 de diciembre de 2024", "nota": "Un fragmento. La cara B solo conserva restos ilegibles de otras inscripciones. I.Dodone DVC 3055A queda sin observaciones propias.", "items": [{"id": "3055A", "dialect": "tesalio", "sub": null, "date": "Mediados del s. IV a.C.", "text": "[Ζεῦ Νάϊ]ε Διώνα Θέμι, ἐ͂ γε̣ν̣[εὰ ἐσσεῖται ἐρ]-\n[σεντέρ]α ἐκ Κούας Θέγειτος ΗΛ[- - -];", "obs": null}, {"id": "3056A", "dialect": "sinClasificar", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "[- - -]ν λώϊον καὶ ἄμ̣[εινον πράσσοι - - -]", "obs": "Grabada debajo de I.Dodone DVC 3055A."}], "facsimiles": []}, {"key": "M1054", "siglum": "M1054", "ami": "ΑΜΙ 13086", "anio": 2024, "fecha": "12 de diciembre de 2024", "nota": "Seis fragmentos. I.Dodone DVC 3114B y 3115B quedan sin observaciones propias.", "items": [{"id": "3113A", "dialect": "tesalio", "sub": "Pelasgiótide", "date": "Finales del s. IV a.C.", "text": "[θεὸς τύχα]ν ἀγαθάν· Ζεῦ̣ Δ[ω]-\n[δωναῖε καὶ Δι]ώνη<ι>· Καλλιρόα ἐπερω-\n[τᾶι τὸν θεὸ]ν καὶ τὰν θεὸν περὶ τᾶς \n[- - - κορ]άουν τοῖς θεοῖς τοῖς θε-\n[- - -] αἰ ἔστιν οἱ βέλτιον καὶ \n[ἄμεινον - - - θ]εραπεύονσαν εἲ πὲρ τ-\n[- - -]ν̣ καὶ τᾶς παγκλαρ̣ίας \n[- - -] τ̣οῖ κατ<ε>ιγνείτοιο αἰ ἀρκέ-\n[σει - - -] εἲ σούσεται πὲρ τᾶς κό-\n[ρας - - -] γάμοιο Ἀν̣δρομά-\n χας", "obs": "Emplea la sigma lunar en todo el texto. Cf. cap. 7, §3.1.1.1 y §5.2."}, {"id": "3114B", "dialect": "tesalio", "sub": null, "date": "Finales del s. IV a.C.", "text": "ἐπε[ρωτᾶι ὁ δεῖνα τὸν] \nΔία τὸν Νᾶον καὶ τ[ὰν Διώ]-\nναν [- - -]\nλά̣θωμαι [. . .]ΚΑΜΟ[- - - ἐλ]-\nθὼν γενειθεῖ ΤΕ[- - -]- \nΘ̣ΕΝ Καλεινίκα [- - -]", "obs": null}, {"id": "3115B", "dialect": "noJonAt", "sub": null, "date": "Finales del s. IV a.C.", "text": "[- - -]ΔΡΙΩ̣[- - -] \n[- - - - - - - - - -]\n[. .] Διώναν καὶ ξενι[- - -] \nπὰρ τοῦ [- - -]-\nκωνος [. . .]ΜΙΧΙ[.][- - -] \nΝΙ[- - -] \n[- - -] ἐπρίατο [- - -]", "obs": null}], "facsimiles": []}, {"key": "M1064", "siglum": "M1064", "ami": "ΑΜΙ 13091", "anio": 2024, "fecha": "13 de diciembre de 2024", "nota": "Un fragmento. La cara B conserva, además, restos de otras inscripciones.", "items": [{"id": "3142A", "dialect": "mezcla", "sub": null, "date": "Mediados del s. III a.C.", "text": "ἐπερωτᾶι [ὁ δεῖνα] \nΔία Νᾶον κ̣[αὶ Διώναν ἦ] \nκοινὰς εἶμε[ν - - -] \nὀνειότερό̣ν ἐ̣σ̣τ[ι - - -] \nΦΟΙΕΣΟΥΤΑ[- - -]", "obs": "La superficie está muy erosionada. Emplea la sigma lunar de trazos rectos. Cf. cap. 12, §4.3, y cap. 13, §4.2."}, {"id": "3143A", "dialect": "sinClasificar", "sub": null, "date": "S. III a.C.", "text": "Α", "obs": "Una sigma lunar de trazos rectos, como la de I.Dodone DVC 3142A, grabada encima de la alfa."}, {"id": "3144B", "dialect": "noJonAt", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "[. . . . 8 . . . .] καὶ τᾶι [- - -]\nκαὶ εἰς τὸν ἔπειτ[α χρόνον - - -] \n[.]ΟΝ[. . .]ΗΔΕ[. .][- - -] \n[. .]ΑΓ[. . . . 8 . . . .][- - -]", "obs": "Trazos finos e irregulares. En la línea 3, donde la edición lee ΟΝ[. . .], se lee al microscopio ΟΕ, un guion y un hueco de unas tres letras. Cf. cap. 15 (anexo)."}, {"id": "3145B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - -]Μ̣ΕΑΛΑ̣Σ̣ Φίμας", "obs": "Grabada en sentido inverso al de I.Dodone DVC 3144B y encima de ella."}], "facsimiles": []}, {"key": "M1125", "siglum": "M1125", "ami": "ΑΜΙ 13184", "anio": 2024, "fecha": "13 de diciembre de 2024", "nota": "Cinco fragmentos. La cara B conserva, además, restos de otras inscripciones.", "items": [{"id": "3354A", "dialect": "severior", "sub": null, "date": "Finales del s. V a.C.", "text": "[θε]ός· Αὐτάριον Παρμενίσκω ἐ̣κ̣ Τάτα[ς - - -] \n[.]Ν Παρεσίναν Ζ̣ο̅ΐλαν [. .]ΡΕΟΙ Παρμε[- - -] \nΜ[. . . .]ΟΙ[. . .]ΝΟΝ[. . . 6 . . .] ἐρ̣γάζεσθαι [. .][- - -]", "obs": "Trazos muy irregulares, como si se hubieran grabado sin un soporte firme. Parece de la misma mano que I.Dodone DVC 3356B. Cf. introducción, §3.2.3, y cap. 6, §3 y §4.1.1."}, {"id": "3355B", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "ἐπικο[ι]νῆται Σωκλῆς [- - -]\n[- - - - - - - - - - - - - - -]", "obs": "Al final de la línea 1 se lee ΟΣΑ, que la edición no recoge."}, {"id": "3356B", "dialect": "noJonAt", "sub": null, "date": "Ss. V-IV a.C.", "text": "Παρμενίσκος κέληται ἐλεύθερον ἀπίμεν [- - -]\nΑΓΛΕ[. .]ΗΝΕ[.]ΡΑ[. . .5 . .]ΩΤ̣Ι δόμεν [.]Ε[. . .5 . .][- - -]\nΑΤ̣Α[. . .5 . .]Ν[. .]Α[. . . 6 . . .] ἀργύριον ἀποδόμεν [- - -]", "obs": "Cara muy deteriorada; las letras se han borrado en parte desde la lectura de la edición. La ómicron final de Παρμενίσκος podría ser una omega, porque tiene otros trazos. En ἐλε<ύ>θερον no hay ípsilon, y la theta lleva una cruz en su interior. Cf. introducción, §3.2.3, y cap. 6, §4.1.2."}], "facsimiles": []}, {"key": "M1154", "siglum": "M1154", "ami": "ΑΜΙ 13209", "anio": 2024, "fecha": "13 de diciembre de 2024", "nota": "I.Dodone DVC 3472A, 3474B, 3475B y 3476B quedan sin observaciones propias.", "items": [{"id": "3472A", "dialect": "noJonAt", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "Ἀγαθᾶι τύχα[ι]. \nἘπικοινῆται Παρμενείδ-\nας τῶι Δι[ὶ] τῶι Νάωι καὶ τᾶι \nΔιώναι λῷϊον καὶ ἄμ- [ει]νον οἴκ[ο]ι μένοντι.", "obs": null}, {"id": "3473A", "dialect": "dorico", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "ἐπερωτῆι Σιλαν[ὸς τὸν Δία τὸν Νάϊον] \nκαὶ τὰν Διώναν πε[ρὶ παρμονᾶς ἦ τὸν οἰ]-\nκ̣έταν τ̣ὸν ἀπείλα̣[φα - - -]\nτὸν ἀπ' Ἀκτίου ἐπριάμ̣[αν - - -] \nΔωδωναίο[ι]ς ὅσαπερ [- - - καὶ] \nἦ ἐσε͂ται πα[ράμονος - - -]", "obs": "Emplea la Η, pero no el dígrafo ΕΙ para la /eː/ de ἐσε͂ται, y la sigma de la línea 1 curva sus trazos medios hacia la forma lunar. Cf. cap. 4, §4.1.3, y cap. 5, §2."}, {"id": "3474B", "dialect": "noJonAt", "sub": null, "date": "Mediados del s. IV a.C.", "text": "ἐπερωτῆι Δία̣ [Νάϊον καὶ Διώναν - - -]-\nανίκα τί[νι κα θεῶν θύουσα - - -]", "obs": null}, {"id": "3475B", "dialect": "noJonAt", "sub": null, "date": "Mediados del s. IV a.C.", "text": "ἐπικοινῆτ̣αι Σανίας \nτῶι [Διὶ τῶι Ναΐωι - - -] \n[- - - - - - - - - - - - -]\nλώϊον καὶ ἄμειν[ον - - -]", "obs": null}, {"id": "3476B", "dialect": "sinClasificar", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "οἴκοι", "obs": null}], "facsimiles": []}, {"key": "M1206", "siglum": "M1206", "ami": "ΑΜΙ 13269", "anio": 2024, "fecha": "13 de diciembre de 2024", "nota": "Dos fragmentos, ambos con una marca en el centro, como si se hubieran aplastado. I.Dodone DVC 3649A y 3650B quedan sin observaciones propias.", "items": [{"id": "3648A", "dialect": "mezcla", "sub": null, "date": "Mediados del s. IV a.C.", "text": "ἐπερωτᾶι Δικαῖ[ος τὸν Δία τὸν Νάϊ]-\nον καὶ τὰν Διώνα[ν ἦ λώϊον] \nκαὶ ἄμεινόν ἐστι : [. .][- - -]-\nΤΙ ποτὶ Πύ̣ρρον καὶ [- - -]", "obs": "En la línea 1, la rho de ἐπερωτᾶι tiene un trazo superior. Cf. cap. 13, §4.2."}, {"id": "3649A", "dialect": "sinClasificar", "sub": null, "date": "Mediados del s. IV a.C.", "text": "Φιλίσ[τα] \nΔΙΝ[. . .5 . .]ΟΣ", "obs": null}, {"id": "3650B", "dialect": "sinClasificar", "sub": null, "date": "Mediados del s. IV a.C.", "text": "Ῥέαν [ἱλασκ]ο̣μένα \nΛ[. . .] εὖ ἔχω;", "obs": null}], "facsimiles": []}, {"key": "M1258", "siglum": "M1258", "ami": "ΑΜΙ 13389", "anio": 2024, "fecha": "16 de diciembre de 2024", "nota": "Dos fragmentos. La cara B conserva, además, restos de otras inscripciones.", "items": [{"id": "3813A", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "περὶ σωτηρί[ας - - -]\nαὐτῶ καὶ τῶ[ν - - -]-\nόντω(ν)", "obs": "Grabada encima de I.Dodone DVC 3814A. En la línea 1, la letra que la edición lee como Η en σωτε̄ρί[ας] es una épsilon corintia: el autor parece haber trazado una Η sin el trazo derecho y haberla completado después como épsilon corintia, como si vacilara entre las dos grafías."}, {"id": "3814A", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "περὶ σίτου", "obs": "Grabada debajo de I.Dodone DVC 3813A."}, {"id": "3815A", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[ἐπερωτῆι τ]ὸν θε[ὸν] Διοχάρη̣[ς] \n[- - -] αὐτ[ῶι γ]ενέσ̣θαι τὰ \n[- - -] χ[ρ]ήματ[α - - -] \n[- - -]ΟΥΣ[- - -]", "obs": "Grabada en sentido inverso al de I.Dodone DVC 3814A."}, {"id": "3816B", "dialect": "noJonAt", "sub": null, "date": "S. IV a.C.", "text": "[θεὸς τύχα ἀγαθά· ὁ δεῖνα] ἐπερωτῆι τὸν Δία \n[τίνι κα θύων θεῶ]ν ἢ ἡρώων ἐπὶ τὸ \n[- - - κ]αταπορεύοιντο", "obs": "La laminilla estaba en mejor estado cuando se grabó, porque faltan letras en la parte izquierda. Cf. cap. 15 (anexo)."}, {"id": "3817B", "dialect": "tesalio", "sub": null, "date": "S. IV a.C.", "text": "θεοί· Ḥιππόλοχος ἐπ̣[ερωτῆι τὸν Δία τὸν Δ]-\nεἶ λώϊ(ο)ν \nουδωναῖον καὶ τὰν [Διώναν - - -]\nνῦν τᾶ̣ς τέχν[ας] Ε[- - -]-\nΝ ἀδαμεύτων ΤΑ[- - -]-\nΡΟΝΩΝ ταῦ̣τα [- - -]-\nΕΝΩΝ καὶ Α̣[. . .][- - -]", "obs": "Letras finas e irregulares, más regulares hacia la derecha. La línea 2 se grabó entre las líneas 1 y 3, después de estas. La primera ómicron de la línea 3, en [Δ]ουδωναῖον, no se lee con claridad, aunque se intuyen sus trazos. La ípsilon tiene tres formas distintas. En la línea 7, donde la edición lee ΕΝΩΝ, parece leerse ΕΡΙΩΝ. Cf. cap. 7 (anexo)."}], "facsimiles": []}, {"key": "M1278", "siglum": "M1278", "ami": "ΑΜΙ 13359", "anio": 2024, "fecha": "13 de diciembre de 2024", "nota": "", "items": [{"id": "3871", "dialect": "noJonAt", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "θεός - τύχα· Χοιρίνα ἐρωτ[ῆι - - -]-\nΕ ἐπὶ τὸν ὄλβον τᾶς θεοῦ τὸ Τ[- - -] \nτᾶς ματρὸς πότερα ὡς ὁσία[ν - - -] \n[δ]όμεν ἱαρῶ ΤΟ[.]Σ̣Ο̣Ν[. .]Ν[.][- - -]", "obs": "Solo θεός se escribe con épsilon corintia, cuya forma coincide con la de la beta de ὄλβον; el resto del texto emplea la Ε. Escritura caligráfica y regular. Cf. cap. 15 (anexo)."}], "facsimiles": []}, {"key": "M10", "siglum": "M10", "ami": "ΑΜΙ 11503", "anio": 2025, "fecha": "octubre de 2025", "nota": "", "items": [{"id": "LOD 113", "dialect": "doricoNO", "sub": null, "date": "Ss. IV-III a.C.", "text": "Ἀγαθᾶι τύχαι. Ἐπικοινῆται Σάτυρος τῶι Διὶ τῶι Νάω̣ι \nκαὶ τᾶι Διώναι - οὐκ ἀνεθέθη ὁ Σατύρου σκύφος - ἐν Ἐλέαι \nἂν τὸν κέλητα τὸν Δωριλάου ὁ κ(έλης) ἀπ'  Ἀκτίου ἀπέτιλε.", "obs": "Las letras son regulares y la lectura es segura en la mayor parte del texto. Se confirman la theta de ἀγαθᾶι y la phi de σκύφος, frente al Σκῦθος de la primera lectura de Evangelidis. Tras Διώναι, en la línea 2, los trazos son superficiales y no incisos como los del resto del texto, sobre todo en ΟΥΚ, que no está unido a lo anterior. Al final de la línea 2 se lee con claridad la iota de Ἐλέαι, sin rastro de una ny; la laminilla ya estaba partida cuando se grabó, y el autor escribió esa letra en el hueco, de modo que la corrección ἐν Ἐλέα<ν> no tiene apoyo en la lectura. En la línea 3 se leen ὄκ᾽ y ἀπέπλε̄, como propone Méndez Dosuna (2007e), y no el ὁ κ(έλης) y el ἀπέτιλε de la edición de Lhôte. Cf. cap. 5, §2 y §5.1.1."}], "facsimiles": []}, {"key": "M11", "siglum": "M11", "ami": "ΑΜΙ 8935", "anio": 2025, "fecha": "octubre de 2025", "nota": "Un fragmento, expuesto en el Museo Arqueológico de Ioánina. En la otra cara se distinguen algunas letras, sin orden ni sentido.", "items": [{"id": "LOD 88", "dialect": "doricoNO", "sub": null, "date": "Tercer cuarto del s. V a.C.", "text": "῏Ε ἀποδάμο̅ν τύ-\nχοιμί κα \nἐπὶ τὰν τέχναν ;", "obs": "La lectura es segura y coincide con el facsímil de Evangelidis. El alfabeto corintio solo se reconoce por la épsilon; no hay otras letras diagnósticas. Las dos chi, una en cruz y otra en aspa, son variantes de la misma letra. Cf. cap. 5, §2."}], "facsimiles": []}, {"key": "M68", "siglum": "M68", "ami": "ΑΜΙ 11985", "anio": 2025, "fecha": "octubre de 2025", "nota": "Parte de la superficie está cubierta por cinta adhesiva, que dificulta la lectura de la cara B.", "items": [{"id": "35A", "dialect": "mezcla", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "Θεός τύχαι ἀγαθᾶι καὶ Διὶ Προ̣νάωι καὶ Διώναι· Πορῖνος \nΚυμαῖος Εὐανδρου εἰρωτᾶ τὸν θεὸν εἰ τὸν ξατράπην \nκαὶ ὕπαρχον θεραπεύοντ[ι] λώιον καὶ ἄμεινον ἔσται", "obs": "Lectura segura. Cf. cap. 10, §4.1, y cap. 13."}, {"id": "36B", "dialect": "noJonAt", "sub": null, "date": "Finales del s. V a.C.", "text": "θεὸς τύχα ἀγαθά• Φ̣ιλοτίδος τὰ σιδά-\nρια δικαίο̅ς;", "obs": "La cinta adhesiva que cubre esta parte de la laminilla impide comprobar la lectura con seguridad. Cf. cap. 15 (anexo)."}, {"id": "37B", "dialect": "jonicoAtico", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "Πορῖνος ξατράπην", "obs": "La cinta adhesiva dificulta la lectura. La forma de las letras parece coincidir con la de I.Dodone DVC 35A, salvo la ómicron, de menor tamaño, lo que es compatible con que la grabara la misma mano, pero no lo demuestra. Cf. cap. 10, §4.1 y §4.7."}], "facsimiles": []}, {"key": "M93", "siglum": "M93", "ami": "ΑΜΙ 12170", "anio": 2025, "fecha": "octubre de 2025", "nota": "Cuatro fragmentos. La cara A conserva, además, restos de otras inscripciones.", "items": [{"id": "95A", "dialect": "mezcla", "sub": null, "date": "Finales del s. IV a.C.", "text": "[Ζ]εῦ Ναῖε καὶ Διώνη καὶ σύν[ναοι, αἰτῶ] [ὑ]μᾶς ἀγαθεῖ τύχει δοῦνα[ι ἐμοὶ] [γ]ᾶν ἐργαζομένωι καὶ ΕΝ [.] [---]", "obs": "Letras regulares y esquemáticas, de trazo profundo, salvo la sigma lunar, de trazos más finos e irregulares, que el facsímil reproduce bien; el alfabeto es el jónico reformado. La primera ípsilon, que el facsímil dibuja como V, tiene la misma forma que las demás. Cf. cap. 13."}, {"id": "96B", "dialect": "jonicoAtico", "sub": "Jónico", "date": "Primera mitad del s. IV a.C.", "text": "[- - -]Ρ̣ΟΝ τὸ ἐκ τοῦ ἀδελφεοῦ εἰ ἔστι ΕΞ[- - -]", "obs": "Letras muy irregulares y más cursivas que las de I.Dodone DVC 95A, cuya escritura, regular y de trazo profundo, parece la de una mano profesional; la lectura es segura. En la línea 1 no se distingue la rho, que la edición da como dudosa, pero sí la ómicron siguiente. Cf. cap. 10, §4.1."}], "facsimiles": []}, {"key": "M185", "siglum": "M185", "ami": "ΑΜΙ 12294", "anio": 2025, "fecha": "octubre de 2025", "nota": "Un fragmento. Las marcas de corte muestran que la laminilla se recortó después de grabarse las inscripciones.", "items": [{"id": "186A", "dialect": "beocio", "sub": null, "date": "Segunda mitad del s. V a.C.", "text": "ἐ͂ καὶ ἐν Ὀρχομενο͂ι;", "obs": "Lectura confirmada. Las inscripciones de las dos caras (I.Dodone DVC 186A, 187A, 188A y 190B) son de una misma mano, aunque varían el tamaño y la profundidad de las letras. La ómicron de Ὀρχομενο͂ι lleva un punto central, como la de I.Dodone DVC 296A y la de I.Dodone DVC 190B. Cf. cap. 8."}, {"id": "187A", "dialect": "beocio", "sub": null, "date": "Segunda mitad del s. V a.C.", "text": "ἐ͂ καὶ hόπαι (ἱ)κανο͂ς φέρει;", "obs": "Lectura confirmada, de la misma mano que I.Dodone DVC 186A. Cf. cap. 8, §4.4.1."}, {"id": "188A", "dialect": "sinClasificar", "sub": null, "date": "S. V a.C.", "text": "[- - -] σαμῖον [.][- - -]", "obs": "De la misma mano que I.Dodone DVC 186A y 187A. Tras σαμῖον se distingue un trazo vertical, quizá una iota, que el facsímil no recoge. Cf. introducción, §3.2.2."}, {"id": "189A", "dialect": "sinClasificar", "sub": null, "date": "S. V a.C.", "text": "[. . . .]ΕΙ[.]ΟΣΑ ἐλθόντα [- - -]\nΣΜ[. . .5 . .]Α[- - -]\n[. .]Α[.]ΕΟΝΕ[- - -]", "obs": "Prácticamente ilegible."}, {"id": "190B", "dialect": "beocio", "sub": null, "date": "Mediados del s. V a.C.", "text": "γᾶν Ϝοικε͂ι πότερα \nἐν Ὀπόεντι;", "obs": "Letras regulares y claras, de la misma mano que las de la cara A: sus trazos son muy parecidos, y la rho y la phi coinciden con las de I.Dodone DVC 187A. La segunda ómicron de la línea 2 lleva un punto central, como en I.Dodone DVC 186A, 296A y 310B. Cf. cap. 8."}], "facsimiles": []}, {"key": "M195", "siglum": "M195", "ami": "ΑΜΙ 12263", "anio": 2025, "fecha": "octubre de 2025", "nota": "La cara B conserva cuatro inscripciones; el fragmento de la derecha está muy deteriorado. I.Dodone DVC 229B queda sin observaciones propias.", "items": [{"id": "226B", "dialect": "noJonAt", "sub": null, "date": "Tercer cuarto del s. V a.C.", "text": "Φειδίας τὸν κλᾶρον \nπερ' ἑαυτο͂ καὶ χ[ρ]ημάτ[ο̅ν καὶ] \nπὲρ τᾶς νόσο̣̅", "obs": "Trazos regulares y profundos. La lectura es segura, salvo la chi de la línea 2, que queda en un pliegue, y la última ómicron, que no se distingue. Las letras son las del alfabeto jónico, salvo la rho, que quizá apunte a una época de transición. Cf. cap. 15 (anexo)."}, {"id": "227B", "dialect": "mezcla", "sub": null, "date": "Principios del s. IV a.C.", "text": "ἴασ(σ)αν ἀλλοῖ ΕΧΟΝ[. . . .]ΜΙΝ[- - -] \nΠαμφίλα ἐρωτᾶ ἐς τί [- - -]", "obs": "Grabada entre las líneas de I.Dodone DVC 226B, cuyos trazos cubre, y por tanto posterior a ella; su segunda línea se superpone a la de I.Dodone DVC 226B. Lectura segura. Cf. cap. 13."}, {"id": "228B", "dialect": "dorico", "sub": null, "date": "Principios del s. IV a.C.", "text": "θεὸς τύχα ἀγαθά• \nἈριστόδαμος ἐπ[ικ]οινῆται Διὶ \nΝαΐωι καὶ Διώναι καὶ θεῶν <ἦ> \nἦ λώϊον καὶ ἄμεινον ΣΑΤΕΙ \nπλέοντι [κατὰ θάλασσ]αν καὶ ἐς \nΦάρον \nτοῦ θέρεος", "obs": "Grabada en sentido inverso al de I.Dodone DVC 226B y 227B y, al parecer, debajo de I.Dodone DVC 229B. Es muy difícil de leer, pero Φάρον se distingue bien, y en la última línea, borrada en gran parte, se reconocen los trazos que recoge la edición. Cf. cap. 4, §2."}, {"id": "229B", "dialect": "jonicoAtico", "sub": "Jónico", "date": "S. IV a.C.", "text": "Νεττείδης (ἐ)περωτᾶ [. .][- - -]\nφια(λ)έων ὧν πέρυσιν ἀπώλεσ̣[α - - -] \nεὑρε͂ν καὶ Μ[.]ΚΑΤΑΦΙΛ[. .]ΝΑ̣ΙΟ ἔχων ἀλλ' ἔστι μο[ι] \nεὑρε͂ν αὐτοῦ", "obs": null}], "facsimiles": []}, {"key": "M210", "siglum": "M210", "ami": "ΑΜΙ 12298", "anio": 2025, "fecha": "octubre de 2025", "nota": "Tres fragmentos, con la línea de corte que señala la edición. I.Dodone DVC 300A queda sin observaciones propias.", "items": [{"id": "296A", "dialect": "beocio", "sub": null, "date": "Segunda mitad del s. V a.C.", "text": "θ[ε]ὸς τύχαν ἀ[γαθάν]• \nΜυρδιό̅(ν)δαο : ὅπο̅ς νι[κ]ῆν ὄντ' <ἐς> κῆσε \nἐν ἐνάτας hό̅ρας : δόε̣[ν] αἰ λῶντες [αἰ δὲ μὴ] \nὈρο̅πόνδε με̅δὲν ἴτο̅;", "obs": "Es la más antigua de la cara A, puesto que las demás inscripciones se grabaron encima. La línea 1, con la invocación, se añadió después en el espacio libre, y la tercera, bajo otras inscripciones, apenas se lee. En el nombre aparecen las dos formas de delta que reproduce el facsímil. La línea 2 tiene tres puntos de separación, y no dos como en el facsímil; la tercera, dos. La primera ómicron de la línea 4 lleva un punto central, como en I.Dodone DVC 186A. Cf. cap. 8."}, {"id": "297A", "dialect": "sinClasificar", "sub": null, "date": "Segunda mitad del s. V a.C.", "text": "ἐ̣͂ ἔχε̅;", "obs": "Misma orientación que I.Dodone DVC 296A. Emplea la épsilon corintia."}, {"id": "298A", "dialect": "sinClasificar", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "[- - -] τὸν ναύσταθμον", "obs": "Grabada encima de I.Dodone DVC 296A."}, {"id": "299A", "dialect": "sinClasificar", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "[- - - ὄμμ]ατα ἐ͂ τύχο[ι]μ' ἰαώμενος;", "obs": "Escritura regular, de trazos más marcados que los de I.Dodone DVC 296A."}, {"id": "300A", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "[- - -]ΑΡΟ", "obs": null}, {"id": "301B", "dialect": "sinClasificar", "sub": null, "date": "Segunda mitad del s. V a.C.", "text": "[- - - ἀ]νθρό̅πινον", "obs": "Letras de mayor módulo que las de las demás inscripciones de la cara B."}, {"id": "302B", "dialect": "mezcla", "sub": null, "date": "Mediados del s. IV a.C.", "text": "[πότ]ερα ναυκλαρεῖν ἄμεινον ναῦν \n[ὠνεο]μένους;", "obs": "Grabada debajo de otras inscripciones de la cara B. La Υ está escrita como la reproduce el facsímil. Cf. cap. 13."}, {"id": "303B", "dialect": "sinClasificar", "sub": null, "date": "Mediados del s. IV a.C.", "text": "ἐν Αἰγινίωι ἦ μέν[ω];", "obs": "La autopsia no aporta datos nuevos sobre la lectura. Cf. cap. 7, §1."}, {"id": "304B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - -]ΠΡΑΝΤΙ[- - -]", "obs": "La autopsia no aporta datos nuevos sobre la lectura. Cf. cap. 15."}, {"id": "305B", "dialect": "doricoNO", "sub": null, "date": "Mediados del s. IV a.C.", "text": "ἦ γᾶν ὀ̅νευμένου̣ς;", "obs": "Grabada en sentido inverso al de las demás inscripciones de la cara B, lo que hace improbable que continúe I.Dodone DVC 302B, como se propone en el comentario de la edición. La lectura es segura, salvo las dos últimas letras, que no se distinguen. Cf. cap. 5, §4."}], "facsimiles": []}, {"key": "M211", "siglum": "M211", "ami": "ΑΜΙ 12284", "anio": 2025, "fecha": "7 de octubre de 2025", "nota": "Cuatro fragmentos principales y dos mínimos, desprendidos hace poco.", "items": [{"id": "306A", "dialect": "sinClasificar", "sub": null, "date": "Segunda mitad del s. V a.C.", "text": "ΗΑΡΓΑΙΑΝΝΑϜΟ ἐ͂ λόϊο(ν) βέ(λτιον)", "obs": "Lectura segura, salvo la alfa de ΝΑϜΟ, que no se distingue; en su lugar hay un trazo que no parece de esa letra. Se ha perdido un pequeño fragmento de la parte inferior de la laminilla. Cf. cap. 7 y cap. 14."}, {"id": "307A", "dialect": "tesalio", "sub": null, "date": "Segunda mitad del s. V a.C.", "text": "Φατύλο̅ι πὲρ γαϜρογί(ας)", "obs": "Grabada debajo de I.Dodone DVC 306A. Aunque el tipo de trazo es el mismo, ninguna letra coincide con las de I.Dodone DVC 306A, y el alfabeto es el tesalio (Candel Lozano, en prensa). Cf. introducción, §3.2.5, y cap. 7."}, {"id": "308A", "dialect": "sinClasificar", "sub": null, "date": "Mediados del s. V a.C.", "text": "μιανῖ (ἢ) οὔ;", "obs": "Grabada al revés, en el hueco que quedaba en el primer fragmento, con trazos superficiales e irregulares."}, {"id": "309B", "dialect": "dorico", "sub": null, "date": "Mediados del s. V a.C.", "text": "Ε[. . .5 . .]ΛΑΙΒ̣[. . .]ΝΙ \nἐϜο͂ν", "obs": "Solo se lee con claridad la secuencia ΒϜΟΝ, con épsilon corintia (ἐϝο͂ν). Al final de la primera línea parece leerse una rho y no una ny, aunque la superposición de I.Dodone DVC 310B dificulta la lectura. Cf. cap. 4, §4."}, {"id": "310B", "dialect": "sinClasificar", "sub": null, "date": "Sin datación en la edición", "text": "Ο[- - -]Ο[- - -]ΟΙ", "obs": "Grabada encima de I.Dodone DVC 309B. La primera ómicron lleva un punto central, como en I.Dodone DVC 190B y 296A."}], "facsimiles": ["assets/autopsias/306A-307A/facsimil-306a-307a.jpg"]}, {"key": "M247", "siglum": "M247", "ami": "ΑΜΙ 12304", "anio": 2025, "fecha": "octubre de 2025", "nota": "Un fragmento.", "items": [{"id": "411A", "dialect": "dorico", "sub": null, "date": "Finales del s. VI a.C.", "text": "αἴ τις \nσύνhοδος", "obs": "Grabada encima de I.Dodone DVC 412A, en bustrofedón: la primera línea va de izquierda a derecha y la segunda de derecha a izquierda. Letras muy arcaicas; el facsímil es preciso. Se confirma el alfabeto corintio arcaico, con la iota quebrada y la san. Cf. cap. 4, §3."}, {"id": "412A", "dialect": "sinClasificar", "sub": null, "date": "Finales del s. VI a.C.", "text": "περὶ ἀνδρο-\nπ̣όδο̅ν̣", "obs": "Grabada debajo de I.Dodone DVC 411A, que impide leer su segunda línea. Emplea el mismo alfabeto corintio, con un ductus algo más reciente, pero es de otra mano."}, {"id": "413B", "dialect": "dorico", "sub": null, "date": "Finales del s. VI a.C.", "text": "ἐπιζό̅Ϝοι̣", "obs": "Letras algo superficiales, de una mano distinta de la de la cara A. El alfabeto no es el corintio: la iota tiene tres trazos y no cuatro, y la épsilon no tiene la forma corintia. Cf. cap. 4, §3 y §4.2.5."}], "facsimiles": []}, {"key": "M248", "siglum": "M248", "ami": "ΑΜΙ 12316", "anio": 2025, "fecha": "octubre de 2025", "nota": "Un fragmento, recortado después de grabarse I.Dodone DVC 415A.", "items": [{"id": "414A", "dialect": "dorico", "sub": null, "date": "Finales del s. VI a.C.", "text": "αὐτοῦ καὶ γε-\nνεᾶς hο̅ς οὔπο̅ \nζο͂ι καὶ Ζεῦ ζο͂ι", "obs": "Lectura segura. Emplea el mismo alfabeto corintio arcaico que I.Dodone DVC 411A y 412A, aunque los trazos son distintos. La última ómicron de οὔπο̄, en la línea 2, está escrita debajo, porque la laminilla ya estaba cortada en ese punto. Cf. cap. 4, §3."}, {"id": "415A", "dialect": "dorico", "sub": null, "date": "Finales del s. VI a.C.", "text": "[- - - τ]ίνι κα̣ θε̣[ο͂ν θύο̅ν - - -]", "obs": "En la parte superior de la laminilla, que se recortó después respetando estas letras. Las letras se distinguen mal; se reconoce la iota quebrada corintia. Cf. cap. 4, §3."}, {"id": "416B", "dialect": "sinClasificar", "sub": null, "date": "Finales del s. VI a.C.", "text": "[- - -]ΣΟ̣Π[. .]ΗΑΤ[- - -] \n[- - -]Ι̣ΑΡ[. .]ΑΕΙΡΟ[- - -]", "obs": "Se leen algunas letras más que en la edición, sin sentido. Los trazos de las dos líneas son distintos, de modo que puede tratarse de dos inscripciones. Alfabeto corintio."}], "facsimiles": []}, {"key": "M292", "siglum": "M292", "ami": "ΑΜΙ 12395", "anio": 2025, "fecha": "octubre de 2025", "nota": "Un fragmento.", "items": [{"id": "556A", "dialect": "tesalio", "sub": "Pelasgiótide", "date": "Finales del s. IV a.C.", "text": "θεὸς τύχα ἀγαθά• ἐρωτᾶι Ἀ-\nγιλαΐδας καὶ οἱ συγγενέες \nπὲρ τοῦ ἀρρωστέ̅ματος τ-\nῶν ὀφθαλμῶν τῶν οἱ π-\nατέρες ἀρρωστήσαεν \nαἰ ἔστι κίννι κε θεῶν \nδρᾶντες̣ τοῖς λοιποῖς \nστάμα γενηθείε̅ \nκαὶ ὑγίεια", "obs": "Trazos superficiales y letras muy pequeñas y regulares. Se confirman las lecturas de la edición, también las de ἀρρωστε̄́ματος y γενηθείε̄, con Ε. Cf. cap. 7."}, {"id": "557A", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - -]οις", "obs": "Grabada encima de I.Dodone DVC 556A."}, {"id": "558B", "dialect": "noJonAt", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "Δεινοκράτης ἐπερ[ωτῆι τὸν Δία π]-\nερὶ hυγιείας καὶ εὐ̣[τυχίας τίνι κα εὐχόμε]-\nνος καὶ θύων ἢ hηρ[ώων ἢ θεῶν καὶ] \nνῦν καὶ ἐσς τὸν [ἀ]εὶ κ[αιρὸν λώϊον π]-\nρ]άσ(σ)οι• ἦ τὰν τέχναν̣ [ἐργαζόμενοι καὶ] \nτ̣ίνι κα θύοντες hο[- - - εὖ] \n ποιέο̣[ιεν - - -]", "obs": "Letras pequeñas e irregulares, de trazo superficial. La lectura es segura, salvo en la línea 2, donde la secuencia que la edición lee ΓΙ en hυγιείας parece una Η, porque el trazo horizontal de la gamma está a media altura; en la línea 6, la ípsilon tiene forma de V. La escritura parece más antigua que la de I.Dodone DVC 556A, como suponen los editores. Cf. cap. 15 (anexo)."}, {"id": "559B", "dialect": "sinClasificar", "sub": null, "date": "Finales del s. IV a.C.", "text": "Ἀγι(λαΐδας)", "obs": "Grabada encima de I.Dodone DVC 558B, con letras regulares y algo más profundas. Su Ἀγι(λαΐδας) remite al consultante de I.Dodone DVC 556A."}], "facsimiles": []}, {"key": "M373", "siglum": "M373", "ami": "ΑΜΙ 12472", "anio": 2025, "fecha": "octubre de 2025", "nota": "Dos fragmentos. La cara A conserva restos de varias inscripciones, aunque la edición solo lee I.Dodone DVC 825A.", "items": [{"id": "825A", "dialect": "dorico", "sub": null, "date": "S. IV a.C.", "text": "ἐ͂ κα φ̣έρ-\nε̅ ἵππι-\nον;", "obs": "Letras arcaicas, de trazos algo irregulares; el facsímil es correcto. La letra que los editores leen como phi no tiene ningún trazo propio de esta y es una gamma corintia, como en la lectura κᾱγ̣ρ[οιμες] que se propone en <i>CIOD</i>. Cf. cap. 4, §3."}, {"id": "826B", "dialect": "noJonAt", "sub": null, "date": "S. IV a.C.", "text": "[π]ὲρ τᾶς [- - -]", "obs": "Letras de aspecto arcaico, poco cuidadas. La letra final no es la sigma lunar que leen los editores, que no encaja con las demás formas, sino otra gamma corintia, como la de I.Dodone DVC 825A. Cf. cap. 15 (anexo)."}, {"id": "827B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - - ἐ͂ γ]αοργ[έο̅ - - -]\n[- - -][.]ΟΟ[- - -]", "obs": "Letras muy grandes. La gamma de γ]αοργ[ tiene la misma forma que la letra de I.Dodone DVC 825A y se junta con la última letra de I.Dodone DVC 826B. Cf. introducción, §3.2.2."}, {"id": "828B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - - τί κα π ]ρά̣σσο̅ν̣ [- - -]", "obs": "No se lee nada; la superficie está cubierta de rayas."}], "facsimiles": []}, {"key": "M409", "siglum": "M409", "ami": "ΑΜΙ 12476", "anio": 2025, "fecha": "octubre de 2025", "nota": "Un fragmento.", "items": [{"id": "934A", "dialect": "tesalio", "sub": null, "date": "Primera mitad del s. V a.C.", "text": "Περί νείκειος \nΘειοτιμίδας", "obs": "La letra final del antropónimo es una alfa, como en I.Dodone Lhôte 149 (Θειοτιμίδας): aunque una marca la ha deformado, la lectura es segura, y el facsímil de la edición la reproduce mal. La sigma curva excluye el alfabeto beocio (Candel Lozano, en prensa). Cf. introducción, §3.2.5, y cap. 7."}, {"id": "935A", "dialect": "sinClasificar", "sub": null, "date": "Mediados del s. V a.C.", "text": "Λαοπh[- - -]", "obs": "Grabada después de I.Dodone DVC 934A, con letras mayores; la alfa es redondeada."}, {"id": "936A", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "[- - -]ΑΠΙΑ[- - -]", "obs": "La autopsia no aporta datos nuevos sobre la lectura."}, {"id": "937A", "dialect": "sinClasificar", "sub": null, "date": "Sin datación en la edición", "text": "[- - -]ΕΙ[- - -]", "obs": "No se distingue."}, {"id": "938A", "dialect": "sinClasificar", "sub": null, "date": "Sin datación en la edición", "text": "[- - -]Α", "obs": "No se distingue."}, {"id": "939A", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "ἑ̣σμὸς̣ [. .]ΟΣ", "obs": "Grabada en sentido inverso al de I.Dodone DVC 934A, con letras grandes."}, {"id": "940A", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "[- - -]ΙΑΤ[- - -]", "obs": "Ilegible."}, {"id": "941B", "dialect": "sinClasificar", "sub": null, "date": "Primera mitad del s. V a.C.", "text": "Κλεΐπ(π)ας̣ πα-\n(μπ)αθίαν ΔΙΠΟΝΔ", "obs": "Letras de ductus muy arcaico e irregular. La primera línea es algo más pequeña y de trazos un poco distintos, pero parece de la misma mano que la segunda. Grabada encima de I.Dodone DVC 942B."}, {"id": "942B", "dialect": "sinClasificar", "sub": null, "date": "S. V a.C.", "text": "Ἐμπορ[ῖ]νο[ς]", "obs": "Grabada debajo de I.Dodone DVC 941B, con letras minúsculas, casi ilegibles."}], "facsimiles": ["assets/autopsias/934A/facsimil-934a.jpg"]}, {"key": "M454", "siglum": "M454", "ami": "ΑΜΙ 12521", "anio": 2025, "fecha": "9 de octubre de 2025", "nota": "Un fragmento, recortado por los lados después de grabarse las inscripciones, como muestran las marcas de corte.", "items": [{"id": "1108A", "dialect": "noJonAt", "sub": null, "date": "Mediados del s. V a.C.", "text": "δρυὸς δ' ἀ-\nε̅θαλ(οῦ)ς ἐ͂ τύχ-\nοιμι ἐπικό-\nπτο̅ν hᾶι κα \nhιαρόν;", "obs": "Comienza algo más a la izquierda que I.Dodone DVC 1108A. Su segunda línea, que no recoge la edición, conserva la Β que se atribuía a I.Dodone DVC 1108A y, tres espacios después, ΤΑΝ."}, {"id": "1109A", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "Ἀρ̣ι̣στόνικος \n[- - - - -]", "obs": "Grabada debajo de I.Dodone DVC 1108A y, por tanto, anterior a ella, lo que no concuerda con la fecha que le da la edición, posterior a la de"}, {"id": "1110B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "Ζ̣εῦ [Νάϊε - - -]", "obs": "Cara B, de trazos irregulares, distintos de los de la cara A; letras grandes."}, {"id": "1111B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - - τίνι κα θε]ο͂ν εὐξάμε̣ν[ος - - -]", "obs": "Cara B, de trazos irregulares, distintos de los de la cara A."}, {"id": "1112B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - -]ΡΟ[- - -]", "obs": "Cara B, de trazos irregulares, distintos de los de la cara A."}], "facsimiles": ["assets/autopsias/1108A-1109A/facsimil-1108a-1109a.jpg"]}, {"key": "M513", "siglum": "M513", "ami": "ΑΜΙ 12688", "anio": 2025, "fecha": "octubre de 2025", "nota": "Dos fragmentos, casi separados, con pliegues horizontales que, al cerrarse, dejan a la vista la cara B. I.Dodone DVC 1341B, 1342B y 1343B quedan sin observaciones propias.", "items": [{"id": "1339A", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "ἐν Φαρκαδόνι", "obs": "Trazos profundos, visibles a simple vista, en el primer pliegue. La lectura es segura y coincide con el facsímil. Sus trazos son muy distintos de los de I.Dodone DVC 1340A, de modo que, si ambas pertenecen a la misma consulta, no las grabó la misma mano. Cf. cap. 7, §3.1.1.1."}, {"id": "1340A", "dialect": "tesalio", "sub": null, "date": "Finales del s. V a.C.", "text": "εἰ γ̣αοργ̣έ̣ω [κ]-\nαὶ ἔστι μο̣ι τυ-\nχαῖον", "obs": "Grabada debajo de I.Dodone DVC 1339A, en el segundo pliegue, con trazos muy superficiales, imperceptibles a simple vista, y letras más pequeñas. Cf. cap. 7, §3.1.1.1."}, {"id": "1341B", "dialect": "sinClasificar", "sub": null, "date": "Finales del s. V a.C.", "text": "γα(οργέω)", "obs": null}, {"id": "1342B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "θ̣εός· [ὁ δεῖνα ἐπερωτῆι - - -]", "obs": null}, {"id": "1343B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - -] γενεὰ̣ [- - -]", "obs": null}], "facsimiles": []}, {"key": "M529", "siglum": "M529", "ami": "ΑΜΙ 12679", "anio": 2025, "fecha": "6 de octubre de 2025", "nota": "Tres fragmentos.", "items": [{"id": "1391A", "dialect": "mezcla", "sub": null, "date": "Finales del s. IV a.C.", "text": "[ὁ δεῖνα ἐπερωτᾶι] \n[Δία Νάϊον καὶ] \nΔιώ̣ναν̣ ὑπὲρ τ̣-\nῆς ἐπιγινομένη-\nς γενεᾶς ὅπως \nπαραμόνιμος αὐ-\nτῶ̣ι ἦι τίνι θεῶν ἢ \nθεᾶν εὐχομένωι \n[παρα]μόνιμος ἦι", "obs": "Letras de tamaño variable. Combina la sigma de cuatro trazos con la lunar, que aparece al final, y la omega no tiene la misma forma en todo el texto. La lectura es segura, también la de Διώ̣ναν̣ en la línea 3 y la de θεῶν en la línea 8, aunque las líneas 6 y 9 están cortadas. Cf. cap. 13."}, {"id": "1392B", "dialect": "sinClasificar", "sub": null, "date": "Finales del s. IV a.C.", "text": "Η", "obs": "Solo conserva una Η de gran tamaño."}], "facsimiles": []}, {"key": "M749", "siglum": "M749", "ami": "ΑΜΙ 12803", "anio": 2025, "fecha": "octubre de 2025", "nota": "Un fragmento. Los números de inventario del museo tapan en parte el comienzo de I.Dodone DVC 2103A.", "items": [{"id": "2103A", "dialect": "tesalio", "sub": null, "date": "Segunda mitad del s. V a.C.", "text": "[- - -]ν̣θος περ' ἐφόδου \n[- - -] μαχανᾶς [. .]Υ̣ΧΟ[.]", "obs": "Letras profundas y regulares. El facsímil es preciso, salvo en el espacio tras ΠΕΡ, que no es mayor que el que separa las demás palabras; al final de la línea 2 solo se distingue lo que reproduce. El alfabeto es el tesalio (Candel Lozano, en prensa). Cf. introducción, §3.2.5, y cap. 7."}, {"id": "2104B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "ΠΕΙΑΝ", "obs": "Grabada encima de I.Dodone DVC 2105B y 2106B, con letras grandes y poco profundas. Lectura segura."}, {"id": "2105B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "θεὸ̣[ς τύχα ἀγαθά· - - -]", "obs": "Es la más antigua de la cara B."}, {"id": "2106B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[τ]ὰν ἔφοδ[ον] Ε[. . .]", "obs": "Posterior a I.Dodone DVC 2105B y anterior a I.Dodone DVC 2104B. La lectura coincide con la de la edición. Es de la misma mano que I.Dodone DVC 2103A, con cuyas letras coincide y con la que comparte el tema (ἔφοδος). Cf. cap. 7, §3.1.1.1."}], "facsimiles": ["assets/autopsias/2103A/facsimil-2103a.jpg"]}, {"key": "M764 + M766", "siglum": "M764 + M766", "ami": "ΑΜΙ 12907", "anio": 2025, "fecha": "8 de octubre de 2025", "nota": "Dos fragmentos; en el segundo, doblado, las letras quedan en el borde, pero se leen bien.", "items": [{"id": "2160", "dialect": "jonicoAtico", "sub": null, "date": "Segunda mitad del s. IV a.C.", "text": "[ὁ δεῖνα] ἐ̣ρωτᾶι τὸν Δί(α) τὸν Νάϊ(ο)ν̣ καὶ τὴν Διώνα[ν - - -]", "obs": "La última letra, que los editores leen como alfa y sobre la que restituyen Διώνα[ν], es una ny incompleta, sin ningún trazo horizontal: Διών<η>ν. La lectura elimina la mezcla dialectal. Cf. introducción, §3.2.2, y cap. 13, §4.7."}], "facsimiles": ["assets/autopsias/2160/facsimil-2160.jpg"]}, {"key": "M781", "siglum": "M781", "ami": "ΑΜΙ 12872", "anio": 2025, "fecha": "octubre de 2025", "nota": "Dos fragmentos.", "items": [{"id": "2204A", "dialect": "tesalio", "sub": "Histiótide", "date": "Finales del s. V a.C.", "text": "θεὸς τύχα· Ἀπολλο[- - - ἐπικοινῆται] \nΔιὶ Δουδωναιεῖ ἦ [- - -]\n ΟΣ[- - -]", "obs": "Trazos profundos y ductus regular. La lectura de la edición es segura, también la de Δουδωναιεῖ. Cf. cap. 7, §3.1.1.1 y §7.2."}, {"id": "2205A", "dialect": "sinClasificar", "sub": null, "date": "S. V a.C.", "text": "[- - - τὸν] Δία [τὸν Νάϊον - - -]", "obs": "Grabada debajo de I.Dodone DVC 2204A, con letras mayores."}, {"id": "2206A", "dialect": "sinClasificar", "sub": null, "date": "S. V a.C.", "text": "[- - -] ο̣ἰκέ̣ο̣ν̣τα [- - -]", "obs": "Grabada debajo de I.Dodone DVC 2204A y en sentido inverso; las letras están borradas y casi no se leen."}], "facsimiles": []}, {"key": "M788", "siglum": "M788", "ami": "ΑΜΙ 12892", "anio": 2025, "fecha": "octubre de 2025", "nota": "Un fragmento, de superficie muy oscura.", "items": [{"id": "2228", "dialect": "doricoNO", "sub": null, "date": "Mediados del s. III a.C.", "text": "ἐ͂ ἂν Λάδο̅νι δεῖ μα̣-\nσθεύειν καὶ ἐσεῖται \nλό̅ϊον καὶ ἄμ[εινον];", "obs": "Lectura segura. Trazos poco profundos y letras pequeñas de estilo arcaico, con sigmas lunares de trazos rectos y sin Η ni Ω. La combinación de sigma lunar y ausencia de Η y Ω sugiere que las formas lunares se adoptaron pronto en el Epiro. Cf. cap. 5, §2."}], "facsimiles": []}, {"key": "M792", "siglum": "M792", "ami": "ΑΜΙ 12868", "anio": 2025, "fecha": "octubre de 2025", "nota": "Siete fragmentos, en peor estado del que muestra el facsímil de la edición.", "items": [{"id": "2242A", "dialect": "doricoNO", "sub": null, "date": "Primera mitad del s. V a.C.", "text": "θεὸς τύχα• Εὖκλις περὶ hυγιέ̅ας καὶ σο̅τε̣̅-\nρίας h[έ̅]κε̅ μαντευσούμενος καὶ αὐτοῦ \nκαὶ Ϝοικετᾶν καὶ χρε̅μάτο̅ν τίνι κ[α θεο͂]-\nν καὶ hε̅ρό̅ο̅ν θύο̅ν λό̅ϊον πράσ(σ)οι καὶ εὐχ[όμε]-\nνος", "obs": "Trazos profundos y lectura segura, en disposición pseudoestoiquedón; en la línea 5, por falta de espacio, las letras son más pequeñas, y al final de la línea 4 se ha perdido un fragmento. Es un ejemplo paradigmático de alfabeto corintio, aunque no emplea la san ni la iota quebrada. Cf. cap. 5, §2."}, {"id": "2243B", "dialect": "dorico", "sub": null, "date": "Primera mitad del s. V a.C.", "text": "πότερ(ά) κα τύχο(ι)μι ΑΤΙΕΙΚΙΟ;", "obs": "Letras profundas y regulares; lectura segura. Los trazos coinciden con los de I.Dodone DVC 2242A, aunque no la forma de la alfa y la épsilon, de modo que la identidad de mano es probable, pero no segura. Cf. cap. 4, §3."}, {"id": "2244B", "dialect": "sinClasificar", "sub": null, "date": "S. V a.C.", "text": "ΘΙΥΚΥ", "obs": "Trazos profundos; no parece de la misma mano que I.Dodone DVC 2243B."}, {"id": "2245B", "dialect": "sinClasificar", "sub": null, "date": "Sin datación en la edición", "text": "Α", "obs": "Una sola letra, sin datos nuevos."}], "facsimiles": []}, {"key": "M812", "siglum": "M812", "ami": "ΑΜΙ 12867", "anio": 2025, "fecha": "octubre de 2025", "nota": "Un fragmento, quizá con una línea de corte en la parte inferior.", "items": [{"id": "2304A", "dialect": "sinClasificar", "sub": null, "date": "Segunda mitad del s. V a.C.", "text": "ΘΜ υἱγύα", "obs": "Letras grandes e irregulares, de aspecto arcaico, con gamma lunada; la lectura coincide con el facsímil. Las dos primeras letras podrían ser una theta con punto central y una san, quizá una abreviatura de θεός. La grafía υἱγύα y el uso de un alfabeto concreto sugieren un consultante poco familiarizado con el griego."}, {"id": "2305A", "dialect": "sinClasificar", "sub": null, "date": "Sin datación en la edición", "text": "[- - -]ΑΙ[- - -]", "obs": "De la misma mano que I.Dodone DVC 2304A, con trazos poco profundos, imperceptibles a simple vista."}, {"id": "2306A", "dialect": "sinClasificar", "sub": null, "date": "Sin datación en la edición", "text": "μή;", "obs": "Grabada en sentido inverso al de I.Dodone DVC 2304A y 2305A, con letras grandes e irregulares y trazos superficiales."}, {"id": "2307B", "dialect": "noJonAt", "sub": null, "date": "Ss. V-IV a.C.", "text": "θεό̣ς· ἐ͂ τὰν ἒ̅ ἄ[λλαν ἄγο̅μαι];", "obs": "Se confirma la lectura, salvo la cuarta letra, que es una Υ y no la Σ de la edición. Por el tamaño y la profundidad de las letras, el comienzo (ΘΒΟΥ Ε) y el resto son dos inscripciones distintas, lo que explica la aparente mezcla de alfabetos; la parte inicial tiene la épsilon corintia que reproduce el facsímil. Cf. cap. 15 (anexo)."}, {"id": "2308B", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "ἐ͂ ἄρι[στον - - -];", "obs": "Letras grandes, juntas y de tamaño irregular."}, {"id": "2309B", "dialect": "sinClasificar", "sub": null, "date": "Segunda mitad del s. V a.C.", "text": "ΚΑΤ", "obs": "Grabada en sentido inverso al de las demás inscripciones de la cara B; no falta nada a la izquierda."}], "facsimiles": []}, {"key": "M846", "siglum": "M846", "ami": "ΑΜΙ 12826", "anio": 2025, "fecha": "octubre de 2025", "nota": "Tres fragmentos. I.Dodone DVC 2427B y 2428B quedan sin observaciones propias.", "items": [{"id": "2425A", "dialect": "dorico", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "θεὸς τύχα· \nἐπερωτῶντ[ι] Δωδω-\nναῖοι τὸν θεὸν ἦ ἀ-\nσφαλέω[ς] ἐστὶ μένειν \n[αὐτ]εῖ καὶ αὐτοῖς \n[κ]αὶ χρήμασι", "obs": "Escritura algo cursiva, sin rasgos arcaicos, con la theta de barra horizontal; el alfabeto es el jónico reformado y el facsímil, preciso. En la línea 4 no se lee la primera sigma. La escritura apunta a una fecha muy posterior a la de la edición. Cf. introducción, §3.2.1, y cap. 4, §3."}, {"id": "2426A", "dialect": "noJonAt", "sub": null, "date": "Primera mitad del s. IV a.C.", "text": "[- - - τύχα] ἀγαθά· [- - -]", "obs": "Grabada encima de I.Dodone DVC 2425A, en el margen derecho que esta dejaba libre. Cf. cap. 15 (anexo)."}, {"id": "2427B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[ὁ δεῖνα ἐπερωτῆι τίνα κα θεῶν ἱλα]σ̣κόμε[νος - - -]", "obs": null}, {"id": "2428B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "περ̣' ἐλ[ευθερίας τίνι θε]-\nῶν θύω;", "obs": null}], "facsimiles": []}, {"key": "M954", "siglum": "M954", "ami": "ΑΜΙ 13004", "anio": 2025, "fecha": "octubre de 2025", "nota": "Un fragmento, cortado con precisión. I.Dodone DVC 2756B y 2757B quedan sin observaciones propias.", "items": [{"id": "2755A", "dialect": "noJonAt", "sub": null, "date": "Mediados del s. V a.C.", "text": "[ἐ͂ ὁ δεῖνα] γεο̅ργέο̅ν λό̅ϊόν \n[κα πράσσ]οιμι;", "obs": "Letras pequeñas y regulares, de trazos profundos, en una disposición que parece estoiquedón. Se confirman las lecturas de la edición, salvo la de la primera letra, que la edición lee como gamma (γεο̄ργέο̄ν) y que es, por sus trazos, una digamma. Cf. cap. 15 (anexo)."}, {"id": "2756B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "ΠΡ", "obs": null}, {"id": "2757B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "[- - -]ΡΩ[.]Π[. .]Ο̣Ε[.]ΠΕΡ[- - -]", "obs": null}], "facsimiles": []}, {"key": "M1014", "siglum": "M1014", "ami": "ΑΜΙ 13155", "anio": 2025, "fecha": "octubre de 2025", "nota": "Cuatro fragmentos. La parte derecha de la cara A está blanqueada, quizá con cal, y quedan restos de ese blanqueamiento en la cara B.", "items": [{"id": "2981A", "dialect": "sinClasificar", "sub": null, "date": "Finales del s. IV a.C.", "text": "[- - - περὶ σ]τρατείας Ε[. .] καὶ ταῦτα βέλτιστά ἐστί μοι \n[- - -][.] κομισθέντι μοι βέλτιόν ἐστι ἱππεύειν", "obs": "Grabada debajo de I.Dodone DVC 2982A. Letras pequeñas y regulares, de ductus evolucionado y trazos profundos, aunque poco visibles por el color oscuro de la superficie; el facsímil es preciso. Combina la sigma lunar de trazos rectos con otra más redondeada. Cf. cap. 13."}, {"id": "2982A", "dialect": "mezcla", "sub": null, "date": "Finales del s. IV a.C.", "text": "θεὸς τύχα [ἀγ]αθά· χρῆσθα̣[ι] \nτοῖ(ς) ἱεροῖς επ' ἀγαθᾶ τύχα[ι];", "obs": "Grabada al revés y encima de I.Dodone DVC 2981A, y por tanto posterior a ella, con letras más grandes y arcaicas y trazos más superficiales. Combina formas lunares y no lunares de la sigma, lo que muestra la convivencia de ambas. Cf. cap. 13."}, {"id": "2983B", "dialect": "sinClasificar", "sub": null, "date": "Mediados del s. IV a.C.", "text": "[- - -Ε]ὐριδ̣ίκαι", "obs": "Letras grandes."}, {"id": "2984B", "dialect": "sinClasificar", "sub": null, "date": "S. IV a.C.", "text": "Α", "obs": "Una sola letra, de gran tamaño."}], "facsimiles": []}, {"key": "M1116", "siglum": "M1116", "ami": "ΑΜΙ 13167", "anio": 2025, "fecha": "octubre de 2025", "nota": "Dos fragmentos.", "items": [{"id": "3315A", "dialect": "dorico", "sub": null, "date": "Ss. V-IV a.C.", "text": "θεὸς τύχα· ἦ αὐτε͂ μένων \nΑΧΕ νῦν ὧδε Ϝο̣ικέω;", "obs": "Trazos algo superficiales y ductus regular. ΑΧΕ, en la línea 2, está escrito con letras más grandes que el resto, como reproduce el facsímil, pero con el mismo tipo de trazo; quizá el consultante empezó a escribir su nombre y prefirió precisar la pregunta. Cf. cap. 4."}, {"id": "3316A", "dialect": "mezcla", "sub": null, "date": "Ss. V-IV a.C.", "text": "τύχα ἀγα[θά]· \n[ὁ]μό̣λογος \nπανπε̅σί[α]", "obs": "Grabada al revés, debajo del final de I.Dodone DVC 3315A y, por tanto, anterior a ella. Los trazos son superficiales y solo la línea 2 se ve con claridad, con una lectura segura. Cf. cap. 13."}, {"id": "3317B", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "[γ]ενεὰν Ἄκτορ[ος]", "obs": "Letras grandes y trazos profundos; grabada debajo de I.Dodone DVC 3318B."}, {"id": "3318B", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "[- - -]ΔΑ", "obs": "Ocupa toda la cara con letras muy grandes."}, {"id": "3319B", "dialect": "sinClasificar", "sub": null, "date": "Ss. V-IV a.C.", "text": "[- - - τί κα] ποέ[ο̅ν - - -]\n[- - -] καρπὸν [- - -]", "obs": "Letras más pequeñas que las de I.Dodone DVC 3317B y 3318B."}], "facsimiles": []}, {"key": "150A", "siglum": null, "ami": null, "anio": null, "fecha": null, "nota": "", "facsimiles": [], "items": [{"id": "150A", "dialect": "tesalio", "sub": null, "date": "Mediados del s. V a.C.", "text": "Γενεᾶς ἔννεκα παιδός;", "obs": "La autopsia en la Eforía de Antigüedades de Ioánina confirmó que la forma de las letras se corresponde con el alfabeto epicórico tesalio, como proponen los editores de I.Dodone DVC frente a la atribución de Jeffery (1990: 233, n.º 17) a un alfabeto arcaico de Dodona. El dato respalda la adscripción tesalia de la consulta y convierte a ἔννεκα en su testimonio tesalio más antiguo (cf. cap. 7, §3.2.2)."}]}];
